import { CalendarCheck2, CircleDollarSign, Clock3, ReceiptText, TrendingUp } from "lucide-react";
import { useMemo } from "react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { formatPrice } from "@/lib/clinic";

function localDate(value?: string | null) {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [yearStr, monthStr, dayStr] = value.split("-");
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  return new Date(year, month - 1, day, 12);
}

function monthKey(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function appointmentValue(item: any) {
  return Number(item?.service_price_snapshot ?? item?.service?.price ?? 0) || 0;
}

export function AdminOperationSummary({ appointments }: { appointments: any[] }) {
  const summary = useMemo(() => {
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12);
    const sevenDays = new Date(today);
    sevenDays.setDate(sevenDays.getDate() + 7);

    const nonCancelled = appointments.filter((item) => item.status !== "cancelado");
    const attended = nonCancelled.filter((item) => item.status === "atendido");
    const confirmedOrAttended = nonCancelled.filter((item) => item.status === "confirmado" || item.status === "atendido");
    const pending = nonCancelled.filter((item) => item.status === "pendente" || item.status === "aguardando_pagamento");
    const currentMonth = monthKey(now);
    const monthAttended = attended.filter((item) => String(item.scheduled_date ?? "").startsWith(currentMonth));
    const monthRevenue = monthAttended.reduce((sum, item) => sum + appointmentValue(item), 0);
    const totalRevenue = attended.reduce((sum, item) => sum + appointmentValue(item), 0);
    const averageTicket = attended.length ? totalRevenue / attended.length : 0;
    const confirmationRate = nonCancelled.length ? Math.round((confirmedOrAttended.length / nonCancelled.length) * 100) : 0;
    const upcomingSeven = nonCancelled.filter((item) => {
      if (item.status === "atendido") return false;
      const date = localDate(item.scheduled_date);
      return date && date >= today && date <= sevenDays;
    }).length;

    const chart = Array.from({ length: 6 }, (_, index) => {
      const date = new Date(now.getFullYear(), now.getMonth() - (5 - index), 1, 12);
      const key = monthKey(date);
      const revenue = attended
        .filter((item) => String(item.scheduled_date ?? "").startsWith(key))
        .reduce((sum, item) => sum + appointmentValue(item), 0);
      return {
        month: date.toLocaleDateString("pt-BR", { month: "short" }).replace(".", ""),
        revenue,
      };
    });

    return {
      monthRevenue,
      monthAppointments: monthAttended.length,
      averageTicket,
      confirmationRate,
      upcomingSeven,
      pending: pending.length,
      chart,
    };
  }, [appointments]);

  return (
    <section className="flex min-h-[330px] w-full flex-col rounded-2xl border border-border bg-card p-4 shadow-soft sm:p-5">
      <div className="flex items-start justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <TrendingUp className="size-4.5 text-primary" />
            <h2 className="text-base font-bold tracking-[-0.01em] text-foreground sm:text-lg">Resumo operacional</h2>
          </div>
          <p className="mt-1 text-[10px] text-muted-foreground sm:text-[11px]">Receita contabilizada somente após o atendimento ser concluído.</p>
        </div>
        <span className="rounded-full bg-primary-soft px-2.5 py-1 text-[9px] font-semibold uppercase tracking-wide text-primary">Atual</span>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-2.5 xl:grid-cols-4">
        <MiniMetric icon={CircleDollarSign} label="Receita do mês" value={formatPrice(summary.monthRevenue)} />
        <MiniMetric icon={ReceiptText} label="Ticket médio" value={formatPrice(summary.averageTicket)} />
        <MiniMetric icon={CalendarCheck2} label="Confirmação" value={`${summary.confirmationRate}%`} />
        <MiniMetric icon={Clock3} label="Próximos 7 dias" value={String(summary.upcomingSeven)} />
      </div>

      <div className="mt-4 flex min-h-0 flex-1 flex-col rounded-xl border border-border/70 bg-background/60 p-3">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-sm font-bold text-foreground sm:text-base">Receita realizada</p>
            <p className="mt-0.5 text-[9px] text-muted-foreground">Últimos 6 meses · somente atendimentos concluídos</p>
          </div>
          <div className="text-right">
            <p className="text-xs font-semibold text-primary">{summary.monthAppointments} atendido(s) neste mês</p>
            <p className="text-[9px] text-muted-foreground">{summary.pending} pendência(s) ativas</p>
          </div>
        </div>

        <div className="mt-2 h-[130px] min-h-[130px] w-full text-primary">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={summary.chart} margin={{ top: 8, right: 4, left: -22, bottom: 0 }}>
              <CartesianGrid vertical={false} stroke="currentColor" strokeOpacity={0.08} />
              <XAxis dataKey="month" tickLine={false} axisLine={false} fontSize={9} tick={{ fill: "currentColor", opacity: 0.55 }} />
              <YAxis tickLine={false} axisLine={false} fontSize={8} tick={{ fill: "currentColor", opacity: 0.45 }} tickFormatter={(value) => value >= 1000 ? `${Math.round(value / 1000)}k` : String(value)} />
              <Tooltip formatter={(value: any) => [formatPrice(Number(value ?? 0)), "Receita"]} labelFormatter={(label) => String(label).toUpperCase()} contentStyle={{ borderRadius: 12, fontSize: 11 }} />
              <Area type="monotone" dataKey="revenue" stroke="currentColor" fill="currentColor" fillOpacity={0.1} strokeWidth={2} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>
    </section>
  );
}

function MiniMetric({ icon: Icon, label, value }: any) {
  return (
    <div className="rounded-xl bg-secondary/45 p-3">
      <Icon className="size-3.5 text-primary" />
      <p className="mt-2 truncate text-[10px] font-semibold text-foreground/75 sm:text-[11px]">{label}</p>
      <p className="mt-0.5 truncate text-sm font-semibold sm:text-base">{value}</p>
    </div>
  );
}

import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  Building2,
  CalendarDays,
  Clock3,
  Pencil,
  Plus,
  Save,
  UsersRound,
  X,
  XCircle,
} from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { supabase } from "@/integrations/supabase/client";

const db = supabase as any;

type RentalType = "hour" | "shift" | "day";
type ShiftType = "morning" | "afternoon" | "evening";

function todayIso() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
}

function formatDate(value: string) {
  if (!value) return "—";
  return new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR");
}

function formatMoney(value: unknown) {
  if (value === null || value === undefined || value === "") return "—";
  return Number(value).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function rentalLabel(type: string) {
  if (type === "shift") return "Turno";
  if (type === "day") return "Diária";
  return "Hora";
}

const shiftTimes: Record<ShiftType, [string, string]> = {
  morning: ["08:00", "12:00"],
  afternoon: ["12:00", "18:00"],
  evening: ["18:00", "22:00"],
};

async function loadRoomManagement() {
  const [rooms, professionals, links, reservations] = await Promise.all([
    db.from("rooms").select("id,name,is_active,created_at,updated_at").order("name"),
    db
      .from("professionals")
      .select("id,name,specialty,is_active,deleted_at")
      .eq("is_active", true)
      .is("deleted_at", null)
      .order("name"),
    db.from("room_professionals").select("room_id,professional_id"),
    db
      .from("room_reservations")
      .select(
        "id,room_id,renter_professional_id,renter_name,reservation_date,rental_type,start_time,end_time,amount,notes,status,created_at,updated_at",
      )
      .order("reservation_date", { ascending: true })
      .order("start_time", { ascending: true })
      .limit(300),
  ]);
  for (const result of [rooms, professionals, links, reservations]) {
    if (result.error) throw result.error;
  }
  return {
    rooms: rooms.data ?? [],
    professionals: professionals.data ?? [],
    links: links.data ?? [],
    reservations: reservations.data ?? [],
  };
}

export function AdminRoomReservations() {
  const queryClient = useQueryClient();
  const { data, isLoading, error, refetch, isFetching } = useQuery({
    queryKey: ["admin-room-management"],
    queryFn: loadRoomManagement,
    retry: 1,
  });

  const rooms = data?.rooms ?? [];
  const professionals = data?.professionals ?? [];
  const links = data?.links ?? [];
  const reservations = data?.reservations ?? [];
  const today = todayIso();

  const [roomFormOpen, setRoomFormOpen] = useState(false);
  const [editingRoomId, setEditingRoomId] = useState<string | null>(null);
  const [roomName, setRoomName] = useState("");
  const [roomActive, setRoomActive] = useState(true);
  const [roomProfessionals, setRoomProfessionals] = useState<string[]>([]);
  const [savingRoom, setSavingRoom] = useState(false);

  const [reservationOpen, setReservationOpen] = useState(false);
  const [editingReservationId, setEditingReservationId] = useState<string | null>(null);
  const [roomId, setRoomId] = useState("");
  const [renterMode, setRenterMode] = useState<"professional" | "external">("professional");
  const [renterProfessionalId, setRenterProfessionalId] = useState("");
  const [externalRenterName, setExternalRenterName] = useState("");
  const [reservationDate, setReservationDate] = useState(today);
  const [rentalType, setRentalType] = useState<RentalType>("hour");
  const [shift, setShift] = useState<ShiftType>("morning");
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("09:00");
  const [amount, setAmount] = useState("");
  const [notes, setNotes] = useState("");
  const [savingReservation, setSavingReservation] = useState(false);

  const roomNameMap = useMemo(
    () => new Map(rooms.map((room: any) => [room.id, room.name])),
    [rooms],
  );
  const professionalMap = useMemo(() => {
    const map = new Map<string, { name: string }>();
    for (const professional of professionals) {
      map.set(professional.id, professional as { name: string });
    }
    return map;
  }, [professionals]);
  const linkedByRoom = useMemo(() => {
    const map = new Map<string, string[]>();
    for (const link of links) {
      const current = map.get(link.room_id) ?? [];
      current.push(link.professional_id);
      map.set(link.room_id, current);
    }
    return map;
  }, [links]);

  const upcomingReservations = reservations.filter(
    (reservation: any) => reservation.status === "active" && reservation.reservation_date >= today,
  );
  const historyReservations = reservations
    .filter(
      (reservation: any) => reservation.status !== "active" || reservation.reservation_date < today,
    )
    .slice()
    .reverse();

  const invalidate = async () => {
    await queryClient.invalidateQueries({ queryKey: ["admin-room-management"] });
    await refetch();
  };

  const resetRoomForm = () => {
    setEditingRoomId(null);
    setRoomName("");
    setRoomActive(true);
    setRoomProfessionals([]);
    setRoomFormOpen(false);
  };

  const openNewRoom = () => {
    setEditingRoomId(null);
    setRoomName("");
    setRoomActive(true);
    setRoomProfessionals([]);
    setRoomFormOpen(true);
  };

  const editRoom = (room: any) => {
    setEditingRoomId(room.id);
    setRoomName(room.name ?? "");
    setRoomActive(room.is_active !== false);
    setRoomProfessionals(linkedByRoom.get(room.id) ?? []);
    setRoomFormOpen(true);
  };

  const toggleRoomProfessional = (professionalId: string) => {
    setRoomProfessionals((current) =>
      current.includes(professionalId)
        ? current.filter((id) => id !== professionalId)
        : [...current, professionalId],
    );
  };

  const saveRoom = async () => {
    if (roomName.trim().length < 2) {
      toast.error("Informe o nome da sala.");
      return;
    }
    setSavingRoom(true);
    try {
      const payload = { name: roomName.trim(), is_active: roomActive };
      const result = editingRoomId
        ? await db.from("rooms").update(payload).eq("id", editingRoomId).select("id").single()
        : await db.from("rooms").insert(payload).select("id").single();
      if (result.error) throw result.error;
      const savedRoomId = result.data.id;

      const deleteLinks = await db.from("room_professionals").delete().eq("room_id", savedRoomId);
      if (deleteLinks.error) throw deleteLinks.error;
      if (roomProfessionals.length) {
        const insertLinks = await db
          .from("room_professionals")
          .insert(
            roomProfessionals.map((professionalId) => ({
              room_id: savedRoomId,
              professional_id: professionalId,
            })),
          );
        if (insertLinks.error) throw insertLinks.error;
      }

      toast.success(editingRoomId ? "Sala atualizada." : "Sala cadastrada.");
      resetRoomForm();
      await invalidate();
    } catch (err: any) {
      toast.error("Não foi possível salvar a sala.", {
        description: err?.message || "Erro inesperado.",
      });
    } finally {
      setSavingRoom(false);
    }
  };

  const applyRentalType = (type: RentalType) => {
    setRentalType(type);
    if (type === "hour") {
      setStartTime("08:00");
      setEndTime("09:00");
    } else if (type === "shift") {
      setShift("morning");
      setStartTime("08:00");
      setEndTime("12:00");
    } else {
      setStartTime("08:00");
      setEndTime("22:00");
    }
  };

  const applyShift = (nextShift: ShiftType) => {
    setShift(nextShift);
    const [start, end] = shiftTimes[nextShift];
    setStartTime(start);
    setEndTime(end);
  };

  const resetReservation = () => {
    setEditingReservationId(null);
    setRoomId("");
    setRenterMode("professional");
    setRenterProfessionalId("");
    setExternalRenterName("");
    setReservationDate(today);
    setRentalType("hour");
    setShift("morning");
    setStartTime("08:00");
    setEndTime("09:00");
    setAmount("");
    setNotes("");
    setReservationOpen(false);
  };

  const openNewReservation = () => {
    resetReservation();
    setReservationOpen(true);
  };

  const editReservation = (reservation: any) => {
    const professionalId = reservation.renter_professional_id ?? "";
    const matchedShift = (Object.entries(shiftTimes).find(
      ([, times]) =>
        times[0] === String(reservation.start_time).slice(0, 5) &&
        times[1] === String(reservation.end_time).slice(0, 5),
    )?.[0] ?? "morning") as ShiftType;

    setEditingReservationId(reservation.id);
    setRoomId(reservation.room_id ?? "");
    setRenterMode(
      professionalId && professionalMap.has(professionalId) ? "professional" : "external",
    );
    setRenterProfessionalId(
      professionalId && professionalMap.has(professionalId) ? professionalId : "",
    );
    setExternalRenterName(
      professionalId && professionalMap.has(professionalId) ? "" : (reservation.renter_name ?? ""),
    );
    setReservationDate(reservation.reservation_date ?? today);
    setRentalType((reservation.rental_type ?? "hour") as RentalType);
    setShift(matchedShift);
    setStartTime(String(reservation.start_time ?? "08:00").slice(0, 5));
    setEndTime(String(reservation.end_time ?? "09:00").slice(0, 5));
    setAmount(
      reservation.amount === null || reservation.amount === undefined
        ? ""
        : String(reservation.amount),
    );
    setNotes(reservation.notes ?? "");
    setReservationOpen(true);
    window.requestAnimationFrame(() =>
      document
        .getElementById("room-reservation-form")
        ?.scrollIntoView({ behavior: "smooth", block: "start" }),
    );
  };

  const saveReservation = async () => {
    if (!roomId) {
      toast.error("Selecione a sala.");
      return;
    }
    if (!reservationDate) {
      toast.error("Selecione a data da reserva.");
      return;
    }
    if (!startTime || !endTime || endTime <= startTime) {
      toast.error("Informe um período válido.");
      return;
    }

    const selectedProfessional =
      renterMode === "professional" ? professionalMap.get(renterProfessionalId) : null;
    const renterName =
      renterMode === "professional"
        ? selectedProfessional?.name?.trim()
        : externalRenterName.trim();
    if (!renterName || renterName.length < 2) {
      toast.error("Informe a profissional ou locatária.");
      return;
    }

    const parsedAmount = amount.trim() ? Number(amount.replace(",", ".")) : null;
    if (parsedAmount !== null && (!Number.isFinite(parsedAmount) || parsedAmount < 0)) {
      toast.error("Informe um valor válido.");
      return;
    }

    setSavingReservation(true);
    try {
      const { data: userData } = await supabase.auth.getUser();
      const payload = {
        room_id: roomId,
        renter_professional_id: renterMode === "professional" ? renterProfessionalId || null : null,
        renter_name: renterName,
        reservation_date: reservationDate,
        rental_type: rentalType,
        start_time: startTime,
        end_time: endTime,
        amount:
          parsedAmount === null ? null : Math.round((parsedAmount + Number.EPSILON) * 100) / 100,
        notes: notes.trim() || null,
      };
      const result = editingReservationId
        ? await db
            .from("room_reservations")
            .update(payload)
            .eq("id", editingReservationId)
            .eq("status", "active")
            .select("id")
            .single()
        : await db
            .from("room_reservations")
            .insert({ ...payload, status: "active", created_by: userData.user?.id ?? null })
            .select("id")
            .single();
      if (result.error) throw result.error;
      toast.success(
        editingReservationId ? "Reserva atualizada com sucesso." : "Sala reservada com sucesso.",
        {
          description: editingReservationId
            ? "Os bloqueios antigos foram liberados e o novo período já está indisponível nas agendas vinculadas."
            : "O período já foi bloqueado nas agendas das profissionais vinculadas à sala.",
        },
      );
      resetReservation();
      await invalidate();
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ["professional-room-blocks"] }),
        queryClient.invalidateQueries({ queryKey: ["professional-client-booking-tools"] }),
        queryClient.invalidateQueries({ queryKey: ["professional-date-slots"] }),
        queryClient.invalidateQueries({ queryKey: ["admin-date-availability-slots"] }),
      ]);
    } catch (err: any) {
      toast.error(
        editingReservationId
          ? "Não foi possível atualizar a reserva."
          : "Não foi possível reservar a sala.",
        {
          description:
            err?.message || "Verifique se já existe uma reserva ou atendimento nesse período.",
        },
      );
    } finally {
      setSavingReservation(false);
    }
  };

  const cancelReservation = async (reservation: any) => {
    if (
      !window.confirm(
        `Cancelar a reserva de ${reservation.renter_name} em ${formatDate(reservation.reservation_date)}?`,
      )
    )
      return;
    const result = await db
      .from("room_reservations")
      .update({ status: "cancelled" })
      .eq("id", reservation.id);
    if (result.error) {
      toast.error("Não foi possível cancelar a reserva.", { description: result.error.message });
      return;
    }
    toast.success(
      "Reserva cancelada. Os horários voltaram a seguir a disponibilidade normal das profissionais.",
    );
    await invalidate();
  };

  if (isLoading)
    return (
      <div className="grid min-h-[55vh] place-items-center text-sm text-muted-foreground">
        Carregando salas...
      </div>
    );
  if (error)
    return (
      <div className="grid min-h-[55vh] place-items-center px-5 text-center text-sm text-destructive">
        {error instanceof Error ? error.message : "Não foi possível carregar as salas."}
      </div>
    );

  return (
    <main className="mx-auto max-w-[1180px] px-4 py-7 sm:px-8 sm:py-10">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.16em] text-muted-foreground">
            Ocupação física
          </p>
          <h1 className="mt-2 text-3xl font-semibold">Reservas de Salas</h1>
          <p className="mt-2 max-w-3xl text-sm text-muted-foreground">
            Controle alugueis por hora, turno ou diária. Uma reserva bloqueia automaticamente o
            período para todas as profissionais vinculadas àquela sala.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button type="button" variant="outline" onClick={() => refetch()} disabled={isFetching}>
            {isFetching ? "Atualizando..." : "Atualizar"}
          </Button>
          <Button type="button" variant="outline" onClick={openNewRoom}>
            <Building2 className="size-4" /> Cadastrar sala
          </Button>
          <Button type="button" onClick={openNewReservation}>
            <Plus className="size-4" /> Nova reserva
          </Button>
        </div>
      </div>

      {roomFormOpen ? (
        <section className="mt-6 rounded-3xl border border-primary/15 bg-card p-5 shadow-soft sm:p-6">
          <div className="flex items-center justify-between gap-3">
            <div>
              <h2 className="text-lg font-semibold">
                {editingRoomId ? "Editar sala" : "Cadastrar sala"}
              </h2>
              <p className="mt-1 text-xs text-muted-foreground">
                Vincule as profissionais que normalmente utilizam esta sala.
              </p>
            </div>
            <Button type="button" size="icon" variant="ghost" onClick={resetRoomForm}>
              <X className="size-4" />
            </Button>
          </div>
          <div className="mt-5 grid gap-4 sm:grid-cols-2">
            <div>
              <Label>Nome da sala</Label>
              <Input
                className="mt-2"
                value={roomName}
                onChange={(event) => setRoomName(event.target.value)}
                placeholder="Ex.: Consultorio 4"
              />
            </div>
            <div className="flex items-center justify-between rounded-2xl border border-border px-4 py-3">
              <div>
                <p className="text-sm font-medium">Sala ativa</p>
                <p className="text-[10px] text-muted-foreground">
                  Salas inativas deixam de ser usadas em novas reservas.
                </p>
              </div>
              <Switch checked={roomActive} onCheckedChange={setRoomActive} />
            </div>
          </div>
          <div className="mt-5">
            <Label>Profissionais que utilizam a sala</Label>
            <div className="mt-2 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
              {professionals.map((professional: any) => {
                const selected = roomProfessionals.includes(professional.id);
                return (
                  <button
                    key={professional.id}
                    type="button"
                    onClick={() => toggleRoomProfessional(professional.id)}
                    className={`rounded-2xl border px-3 py-3 text-left transition ${selected ? "border-primary bg-primary-soft" : "border-border hover:border-primary/25"}`}
                  >
                    <div className="flex items-center gap-2">
                      <span
                        className={`grid size-6 place-items-center rounded-full text-[10px] font-bold ${selected ? "bg-primary text-primary-foreground" : "bg-secondary text-muted-foreground"}`}
                      >
                        {selected ? "✓" : "+"}
                      </span>
                      <div className="min-w-0">
                        <p className="truncate text-xs font-semibold">{professional.name}</p>
                        <p className="truncate text-[10px] text-muted-foreground">
                          {professional.specialty || "Profissional"}
                        </p>
                      </div>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
          <div className="mt-5 flex gap-2">
            <Button type="button" variant="outline" onClick={resetRoomForm} disabled={savingRoom}>
              Cancelar
            </Button>
            <Button type="button" onClick={() => void saveRoom()} disabled={savingRoom}>
              <Save className="size-4" /> {savingRoom ? "Salvando..." : "Salvar sala"}
            </Button>
          </div>
        </section>
      ) : null}

      {reservationOpen ? (
        <section
          id="room-reservation-form"
          className="mt-6 scroll-mt-6 rounded-3xl border border-primary/15 bg-card p-5 shadow-soft sm:p-6"
        >
          <div className="flex items-center justify-between gap-3">
            <div>
              <h2 className="text-lg font-semibold">
                {editingReservationId ? "Editar reserva" : "Nova reserva"}
              </h2>
              <p className="mt-1 text-xs text-muted-foreground">
                O sistema impede reservas sobrepostas e também bloqueia reservas quando já existe
                atendimento na sala.
              </p>
            </div>
            <Button type="button" size="icon" variant="ghost" onClick={resetReservation}>
              <X className="size-4" />
            </Button>
          </div>
          <div className="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <div>
              <Label>Sala</Label>
              <Select value={roomId} onValueChange={setRoomId}>
                <SelectTrigger className="mt-2">
                  <SelectValue placeholder="Selecione a sala" />
                </SelectTrigger>
                <SelectContent>
                  {rooms
                    .filter((room: any) => room.is_active || room.id === roomId)
                    .map((room: any) => (
                      <SelectItem key={room.id} value={room.id}>
                        {room.name}
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Locatária</Label>
              <Select
                value={renterMode}
                onValueChange={(value) => {
                  setRenterMode(value as "professional" | "external");
                  setRenterProfessionalId("");
                  setExternalRenterName("");
                }}
              >
                <SelectTrigger className="mt-2">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="professional">Profissional cadastrada</SelectItem>
                  <SelectItem value="external">Nome externo</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {renterMode === "professional" ? (
              <div>
                <Label>Profissional</Label>
                <Select value={renterProfessionalId} onValueChange={setRenterProfessionalId}>
                  <SelectTrigger className="mt-2">
                    <SelectValue placeholder="Escolha" />
                  </SelectTrigger>
                  <SelectContent>
                    {professionals.map((professional: any) => (
                      <SelectItem key={professional.id} value={professional.id}>
                        {professional.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <div>
                <Label>Nome da locatária</Label>
                <Input
                  className="mt-2"
                  value={externalRenterName}
                  onChange={(event) => setExternalRenterName(event.target.value)}
                  placeholder="Nome completo"
                />
              </div>
            )}
            <div>
              <Label>Data</Label>
              <Input
                className="mt-2"
                type="date"
                min={today}
                value={reservationDate}
                onChange={(event) => setReservationDate(event.target.value)}
              />
            </div>
            <div>
              <Label>Tipo de aluguel</Label>
              <Select
                value={rentalType}
                onValueChange={(value) => applyRentalType(value as RentalType)}
              >
                <SelectTrigger className="mt-2">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="hour">Hora</SelectItem>
                  <SelectItem value="shift">Turno</SelectItem>
                  <SelectItem value="day">Diária</SelectItem>
                </SelectContent>
              </Select>
            </div>
            {rentalType === "shift" ? (
              <div>
                <Label>Turno</Label>
                <Select value={shift} onValueChange={(value) => applyShift(value as ShiftType)}>
                  <SelectTrigger className="mt-2">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="morning">Manhã</SelectItem>
                    <SelectItem value="afternoon">Tarde</SelectItem>
                    <SelectItem value="evening">Noite</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <div>
                <Label>Valor do aluguel (opcional)</Label>
                <Input
                  className="mt-2"
                  type="number"
                  min="0"
                  step="0.01"
                  inputMode="decimal"
                  value={amount}
                  onChange={(event) => setAmount(event.target.value)}
                  placeholder="0,00"
                />
              </div>
            )}
            <div>
              <Label>Horário inicial</Label>
              <Input
                className="mt-2"
                type="time"
                value={startTime}
                onChange={(event) => setStartTime(event.target.value)}
              />
            </div>
            <div>
              <Label>Horário final</Label>
              <Input
                className="mt-2"
                type="time"
                value={endTime}
                onChange={(event) => setEndTime(event.target.value)}
              />
            </div>
            {rentalType === "shift" ? (
              <div>
                <Label>Valor do aluguel (opcional)</Label>
                <Input
                  className="mt-2"
                  type="number"
                  min="0"
                  step="0.01"
                  inputMode="decimal"
                  value={amount}
                  onChange={(event) => setAmount(event.target.value)}
                  placeholder="0,00"
                />
              </div>
            ) : null}
            <div className="sm:col-span-2 lg:col-span-3">
              <Label>Observação (opcional)</Label>
              <Textarea
                className="mt-2"
                value={notes}
                onChange={(event) => setNotes(event.target.value)}
                placeholder="Informações sobre a reserva"
              />
            </div>
          </div>
          <div className="mt-5 flex gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={resetReservation}
              disabled={savingReservation}
            >
              Cancelar
            </Button>
            <Button
              type="button"
              onClick={() => void saveReservation()}
              disabled={savingReservation}
            >
              {editingReservationId ? (
                <Save className="size-4" />
              ) : (
                <CalendarDays className="size-4" />
              )}{" "}
              {savingReservation
                ? "Salvando..."
                : editingReservationId
                  ? "Salvar alterações"
                  : "Confirmar reserva"}
            </Button>
          </div>
        </section>
      ) : null}

      <section className="mt-6 rounded-3xl border border-border bg-card p-5 shadow-soft sm:p-6">
        <div>
          <h2 className="text-lg font-semibold">Salas cadastradas</h2>
          <p className="mt-1 text-xs text-muted-foreground">
            As profissionais vinculadas ficam automaticamente bloqueadas quando a sala recebe uma
            reserva administrativa.
          </p>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          {rooms.map((room: any) => {
            const linked = linkedByRoom.get(room.id) ?? [];
            return (
              <article key={room.id} className="rounded-2xl border border-border p-4">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="flex items-center gap-2">
                      <Building2 className="size-4 text-primary" />
                      <p className="font-semibold">{String(room.name)}</p>
                      {!room.is_active ? <Badge variant="secondary">Inativa</Badge> : null}
                    </div>
                    <div className="mt-2 flex flex-wrap gap-1.5">
                      {linked.length ? (
                        linked.map((id) => {
                          const professionalName = professionalMap.get(id)?.name || "Profissional";
                          return (
                            <Badge key={id} variant="outline" className="text-[10px]">
                              <UsersRound className="mr-1 size-3" />
                              {professionalName}
                            </Badge>
                          );
                        })
                      ) : (
                        <span className="text-[10px] text-muted-foreground">
                          Nenhuma profissional vinculada.
                        </span>
                      )}
                    </div>
                  </div>
                  <Button type="button" size="sm" variant="outline" onClick={() => editRoom(room)}>
                    <Pencil className="size-3.5" /> Editar
                  </Button>
                </div>
              </article>
            );
          })}
        </div>
      </section>

      <section className="mt-6 rounded-3xl border border-border bg-card p-5 shadow-soft sm:p-6">
        <div>
          <h2 className="text-lg font-semibold">Próximas reservas</h2>
          <p className="mt-1 text-xs text-muted-foreground">
            Períodos ativos ficam indisponíveis automaticamente nas agendas vinculadas.
          </p>
        </div>
        <div className="mt-4 space-y-3">
          {upcomingReservations.length ? (
            upcomingReservations.map((reservation: any) => (
              <article
                key={reservation.id}
                className="rounded-2xl border border-primary/15 bg-primary/[0.025] p-4"
              >
                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="font-semibold">
                        {String(roomNameMap.get(reservation.room_id) || "Sala")}
                      </p>
                      <Badge>{rentalLabel(reservation.rental_type)}</Badge>
                    </div>
                    <p className="mt-1 text-sm">{String(reservation.renter_name)}</p>
                    <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
                      <span className="flex items-center gap-1">
                        <CalendarDays className="size-3.5" />{" "}
                        {formatDate(reservation.reservation_date)}
                      </span>
                      <span className="flex items-center gap-1">
                        <Clock3 className="size-3.5" /> {String(reservation.start_time).slice(0, 5)}{" "}
                        às {String(reservation.end_time).slice(0, 5)}
                      </span>
                      <span>{formatMoney(reservation.amount)}</span>
                    </div>
                    {reservation.notes ? (
                      <p className="mt-2 text-xs text-muted-foreground">
                        {String(reservation.notes)}
                      </p>
                    ) : null}
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => editReservation(reservation)}
                    >
                      <Pencil className="size-4" /> Editar reserva
                    </Button>
                    <Button
                      type="button"
                      variant="outline"
                      className="text-destructive"
                      onClick={() => void cancelReservation(reservation)}
                    >
                      <XCircle className="size-4" /> Cancelar reserva
                    </Button>
                  </div>
                </div>
              </article>
            ))
          ) : (
            <div className="rounded-2xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
              Nenhuma reserva futura.
            </div>
          )}
        </div>
      </section>

      {historyReservations.length ? (
        <section className="mt-6 rounded-3xl border border-border bg-card p-5 shadow-soft sm:p-6">
          <h2 className="text-lg font-semibold">Histórico de reservas</h2>
          <div className="mt-4 space-y-2">
            {historyReservations.slice(0, 40).map((reservation: any) => (
              <div
                key={reservation.id}
                className="flex flex-col gap-2 rounded-2xl border border-border px-4 py-3 sm:flex-row sm:items-center sm:justify-between"
              >
                <div>
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="text-sm font-semibold">
                      {String(roomNameMap.get(reservation.room_id) || "Sala")}
                    </p>
                    <Badge variant="secondary">
                      {reservation.status === "cancelled" ? "Cancelada" : "Concluída pelo período"}
                    </Badge>
                  </div>
                  <p className="mt-1 text-xs text-muted-foreground">
                    {String(reservation.renter_name)} · {formatDate(reservation.reservation_date)} ·{" "}
                    {String(reservation.start_time).slice(0, 5)} às{" "}
                    {String(reservation.end_time).slice(0, 5)}
                  </p>
                </div>
                <span className="text-xs font-medium">{formatMoney(reservation.amount)}</span>
              </div>
            ))}
          </div>
        </section>
      ) : null}
    </main>
  );
}

import {
  BadgePercent,
  CircleDollarSign,
  Pencil,
  Plus,
  Search,
  Trash2,
  UserRoundCheck,
  WalletCards,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { supabase } from "@/integrations/supabase/client";
import { formatDate, formatPrice } from "@/lib/clinic";

const db = supabase as any;

type SellerForm = {
  id?: string;
  name: string;
  email: string;
  phone: string;
  commissionPercentage: string;
  isActive: boolean;
};

const emptyForm: SellerForm = {
  name: "",
  email: "",
  phone: "",
  commissionPercentage: "2",
  isActive: true,
};

function formatPercentage(value: unknown) {
  const number = Number(value ?? 0);
  return `${number.toLocaleString("pt-BR", { maximumFractionDigits: 4 })}%`;
}

function commissionStatus(status: string) {
  if (status === "pending")
    return { label: "A pagar", className: "bg-emerald-100 text-emerald-800 hover:bg-emerald-100" };
  if (status === "suspended")
    return {
      label: "Aguardando recebimento",
      className: "bg-amber-100 text-amber-800 hover:bg-amber-100",
    };
  return { label: "Cancelada", className: "bg-secondary text-muted-foreground hover:bg-secondary" };
}

export function AdminSellersWorkspace() {
  const [sellers, setSellers] = useState<any[]>([]);
  const [commissions, setCommissions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [archivingId, setArchivingId] = useState("");
  const [dialogOpen, setDialogOpen] = useState(false);
  const [form, setForm] = useState<SellerForm>(emptyForm);
  const [search, setSearch] = useState("");

  const load = async () => {
    setLoading(true);
    const [sellerResult, commissionResult] = await Promise.all([
      db
        .from("sellers")
        .select(
          "id, name, email, phone, commission_percentage, is_active, created_at, updated_at, deleted_at",
        )
        .order("name"),
      db
        .from("seller_commissions")
        .select(
          "id, appointment_id, seller_id, seller_name_snapshot, percentage, base_amount, commission_amount, status, created_at, appointment:appointments!seller_commissions_appointment_id_fkey(patient_name, scheduled_date)",
        )
        .order("created_at", { ascending: false })
        .limit(150),
    ]);

    setLoading(false);
    const error = sellerResult.error ?? commissionResult.error;
    if (error) {
      toast.error("Não foi possível carregar os vendedores.", { description: error.message });
      return;
    }
    setSellers(sellerResult.data ?? []);
    setCommissions(commissionResult.data ?? []);
  };

  useEffect(() => {
    void load();
  }, []);

  const activeSellers = useMemo(
    () => sellers.filter((seller) => seller.is_active && !seller.deleted_at),
    [sellers],
  );

  const receivedSales = useMemo(
    () =>
      commissions
        .filter((item) => item.status === "pending")
        .reduce((sum, item) => sum + Number(item.base_amount ?? 0), 0),
    [commissions],
  );

  const pendingCommission = useMemo(
    () =>
      commissions
        .filter((item) => item.status === "pending")
        .reduce((sum, item) => sum + Number(item.commission_amount ?? 0), 0),
    [commissions],
  );

  const waitingCommission = useMemo(
    () =>
      commissions
        .filter((item) => item.status === "suspended")
        .reduce((sum, item) => sum + Number(item.commission_amount ?? 0), 0),
    [commissions],
  );

  const filteredSellers = useMemo(() => {
    const term = search.trim().toLocaleLowerCase("pt-BR");
    if (!term) return sellers;
    return sellers.filter((seller) =>
      [seller.name, seller.email, seller.phone].some((value) =>
        String(value ?? "")
          .toLocaleLowerCase("pt-BR")
          .includes(term),
      ),
    );
  }, [sellers, search]);

  const openNew = () => {
    setForm(emptyForm);
    setDialogOpen(true);
  };

  const openEdit = (seller: any) => {
    setForm({
      id: seller.id,
      name: seller.name ?? "",
      email: seller.email ?? "",
      phone: seller.phone ?? "",
      commissionPercentage: String(Number(seller.commission_percentage ?? 0)),
      isActive: Boolean(seller.is_active && !seller.deleted_at),
    });
    setDialogOpen(true);
  };

  const save = async () => {
    const name = form.name.trim();
    const percentage = Number(form.commissionPercentage.replace(",", "."));
    if (!name) {
      toast.error("Informe o nome do vendedor.");
      return;
    }
    if (!Number.isFinite(percentage) || percentage < 0 || percentage > 100) {
      toast.error("Informe um percentual entre 0% e 100%.");
      return;
    }

    setSaving(true);
    const { error } = await db.rpc("save_seller", {
      _name: name,
      _commission_percentage: percentage,
      _email: form.email.trim() || null,
      _phone: form.phone.trim() || null,
      _is_active: form.isActive,
      _seller_id: form.id ?? null,
    });
    setSaving(false);

    if (error) {
      toast.error("Não foi possível salvar o vendedor.", { description: error.message });
      return;
    }

    toast.success(form.id ? "Vendedor atualizado." : "Vendedor cadastrado.", {
      description: `${name} · comissão padrão de ${formatPercentage(percentage)}`,
    });
    setDialogOpen(false);
    setForm(emptyForm);
    await load();
  };

  const archive = async (seller: any) => {
    if (
      !window.confirm(
        `Excluir ${seller.name} da lista de vendedores ativos? O histórico de vendas e comissões será preservado.`,
      )
    )
      return;
    setArchivingId(seller.id);
    const { error } = await db.rpc("archive_seller", { _seller_id: seller.id });
    setArchivingId("");
    if (error) {
      toast.error("Não foi possível excluir o vendedor.", { description: error.message });
      return;
    }
    toast.success("Vendedor removido da lista ativa.", {
      description: "O histórico de comissões foi mantido.",
    });
    await load();
  };

  return (
    <section className="mx-auto w-full max-w-[1500px] space-y-5">
      <header className="flex flex-col gap-4 rounded-3xl border border-border bg-card p-5 shadow-soft sm:p-6 lg:flex-row lg:items-center lg:justify-between">
        <div className="min-w-0">
          <div className="flex items-center gap-2 text-primary">
            <BadgePercent className="size-5" />
            <span className="text-xs font-semibold uppercase tracking-[0.16em]">Comercial</span>
          </div>
          <h1 className="mt-2 text-2xl font-semibold tracking-tight">Vendedores e comissões</h1>
          <p className="mt-1 max-w-2xl text-sm text-muted-foreground">
            Cadastre quem indica clientes, defina a porcentagem padrão e acompanhe a comissão gerada
            por cada venda. Este módulo é exclusivo para administradores.
          </p>
        </div>
        <Button type="button" className="h-11 shrink-0 rounded-xl" onClick={openNew}>
          <Plus className="size-4" /> Novo vendedor
        </Button>
      </header>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <SummaryCard
          icon={UserRoundCheck}
          label="Vendedores ativos"
          value={String(activeSellers.length)}
          hint={`${sellers.length} cadastrado(s) no total`}
        />
        <SummaryCard
          icon={WalletCards}
          label="Vendas recebidas"
          value={formatPrice(receivedSales)}
          hint="Base das comissões liberadas"
        />
        <SummaryCard
          icon={CircleDollarSign}
          label="Comissões a pagar"
          value={formatPrice(pendingCommission)}
          hint="Receitas já recebidas"
        />
        <SummaryCard
          icon={BadgePercent}
          label="Aguardando recebimento"
          value={formatPrice(waitingCommission)}
          hint="Comissão suspensa até a entrada"
        />
      </div>

      <div className="rounded-3xl border border-border bg-card p-4 shadow-soft sm:p-5">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-lg font-semibold">Cadastro de vendedores</h2>
            <p className="mt-0.5 text-xs text-muted-foreground">
              Editar a porcentagem altera somente novas indicações; agendamentos já atribuídos
              mantêm o percentual registrado no momento da atribuição.
            </p>
          </div>
          <div className="relative w-full sm:w-[320px]">
            <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Pesquisar vendedor..."
              className="h-10 rounded-xl pl-9"
            />
          </div>
        </div>

        {loading ? (
          <div className="mt-4 rounded-2xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
            Carregando vendedores...
          </div>
        ) : filteredSellers.length === 0 ? (
          <div className="mt-4 rounded-2xl border border-dashed border-border p-8 text-center">
            <UserRoundCheck className="mx-auto size-5 text-muted-foreground" />
            <p className="mt-2 text-sm font-medium">Nenhum vendedor cadastrado.</p>
            <p className="mt-1 text-xs text-muted-foreground">
              Cadastre o primeiro para habilitar a seleção nos agendamentos.
            </p>
          </div>
        ) : (
          <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            {filteredSellers.map((seller) => {
              const active = seller.is_active && !seller.deleted_at;
              return (
                <article
                  key={seller.id}
                  className="rounded-2xl border border-border bg-background/65 p-4"
                >
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0">
                      <p className="truncate font-semibold">{seller.name}</p>
                      <p className="mt-1 truncate text-xs text-muted-foreground">
                        {seller.phone || seller.email || "Sem contato informado"}
                      </p>
                    </div>
                    <Badge
                      variant={active ? "default" : "secondary"}
                      className={active ? "bg-emerald-600 text-white hover:bg-emerald-600" : ""}
                    >
                      {active ? "Ativo" : seller.deleted_at ? "Excluído" : "Inativo"}
                    </Badge>
                  </div>
                  <div className="mt-4 rounded-xl bg-primary-soft/55 p-3">
                    <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                      Comissão padrão
                    </p>
                    <p className="mt-1 text-xl font-semibold text-primary">
                      {formatPercentage(seller.commission_percentage)}
                    </p>
                  </div>
                  <div className="mt-3 flex gap-2">
                    <Button
                      type="button"
                      variant="outline"
                      size="sm"
                      className="flex-1 rounded-xl"
                      onClick={() => openEdit(seller)}
                    >
                      <Pencil className="size-3.5" /> Editar
                    </Button>
                    {!seller.deleted_at ? (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        className="rounded-xl text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                        disabled={archivingId === seller.id}
                        onClick={() => void archive(seller)}
                        title="Excluir vendedor"
                      >
                        <Trash2 className="size-3.5" />
                      </Button>
                    ) : null}
                  </div>
                </article>
              );
            })}
          </div>
        )}
      </div>

      <div className="rounded-3xl border border-border bg-card p-4 shadow-soft sm:p-5">
        <div>
          <h2 className="text-lg font-semibold">Comissões geradas</h2>
          <p className="mt-0.5 text-xs text-muted-foreground">
            A comissão é independente da comissão do profissional e acompanha automaticamente o
            status financeiro da venda.
          </p>
        </div>
        {commissions.length === 0 ? (
          <div className="mt-4 rounded-2xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">
            Nenhuma comissão de vendedor gerada até o momento.
          </div>
        ) : (
          <div className="mt-4 space-y-2">
            {commissions.map((item) => {
              const status = commissionStatus(item.status);
              return (
                <div
                  key={item.id}
                  className="grid gap-3 rounded-2xl border border-border bg-background/65 p-3 sm:grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)_auto] sm:items-center sm:p-4"
                >
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="truncate text-sm font-semibold">{item.seller_name_snapshot}</p>
                      <Badge variant="secondary" className={status.className}>
                        {status.label}
                      </Badge>
                    </div>
                    <p className="mt-1 truncate text-xs text-muted-foreground">
                      {item.appointment?.patient_name ?? "Cliente"}
                      {item.appointment?.scheduled_date
                        ? ` · ${formatDate(item.appointment.scheduled_date)}`
                        : ""}
                    </p>
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div>
                      <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                        Venda
                      </p>
                      <p className="mt-0.5 font-semibold">
                        {formatPrice(Number(item.base_amount ?? 0))}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                        Percentual
                      </p>
                      <p className="mt-0.5 font-semibold">{formatPercentage(item.percentage)}</p>
                    </div>
                  </div>
                  <div className="sm:text-right">
                    <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                      Comissão
                    </p>
                    <p className="mt-0.5 text-base font-semibold text-primary">
                      {formatPrice(Number(item.commission_amount ?? 0))}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <Dialog
        open={dialogOpen}
        onOpenChange={(open) => {
          if (!saving) setDialogOpen(open);
        }}
      >
        <DialogContent className="w-[calc(100%-1rem)] rounded-3xl sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{form.id ? "Editar vendedor" : "Novo vendedor"}</DialogTitle>
            <DialogDescription>
              Defina os dados e a porcentagem padrão usada quando este vendedor for selecionado em
              um agendamento.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-2">
            <div className="space-y-1.5">
              <Label htmlFor="seller-name">Nome *</Label>
              <Input
                id="seller-name"
                value={form.name}
                onChange={(event) =>
                  setForm((current) => ({ ...current, name: event.target.value }))
                }
                disabled={saving}
              />
            </div>
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-1.5">
                <Label htmlFor="seller-phone">Telefone</Label>
                <Input
                  id="seller-phone"
                  inputMode="tel"
                  value={form.phone}
                  onChange={(event) =>
                    setForm((current) => ({ ...current, phone: event.target.value }))
                  }
                  disabled={saving}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="seller-email">E-mail</Label>
                <Input
                  id="seller-email"
                  type="email"
                  value={form.email}
                  onChange={(event) =>
                    setForm((current) => ({ ...current, email: event.target.value }))
                  }
                  disabled={saving}
                />
              </div>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="seller-percentage">Comissão padrão (%) *</Label>
              <Input
                id="seller-percentage"
                type="number"
                min="0"
                max="100"
                step="0.01"
                inputMode="decimal"
                value={form.commissionPercentage}
                onChange={(event) =>
                  setForm((current) => ({ ...current, commissionPercentage: event.target.value }))
                }
                disabled={saving}
              />
              <p className="text-[11px] text-muted-foreground">
                Exemplo: 2 significa 2% do valor efetivamente vendido, após desconto e antes das
                taxas do cartão.
              </p>
            </div>
            <div className="flex items-center justify-between rounded-2xl border border-border p-3">
              <div>
                <p className="text-sm font-medium">Vendedor ativo</p>
                <p className="mt-0.5 text-[11px] text-muted-foreground">
                  Apenas vendedores ativos aparecem no agendamento.
                </p>
              </div>
              <Switch
                checked={form.isActive}
                onCheckedChange={(checked) =>
                  setForm((current) => ({ ...current, isActive: checked }))
                }
                disabled={saving}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)} disabled={saving}>
              Cancelar
            </Button>
            <Button onClick={() => void save()} disabled={saving}>
              {saving ? "Salvando..." : "Salvar vendedor"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </section>
  );
}

function SummaryCard({ icon: Icon, label, value, hint }: any) {
  return (
    <div className="rounded-2xl border border-border bg-card p-4 shadow-soft">
      <div className="flex items-center gap-2 text-primary">
        <Icon className="size-4" />
        <span className="text-[10px] font-semibold uppercase tracking-[0.12em]">{label}</span>
      </div>
      <p className="mt-3 text-xl font-semibold tracking-tight">{value}</p>
      <p className="mt-1 text-[11px] text-muted-foreground">{hint}</p>
    </div>
  );
}

