          <div
            key={session.id}
            className={`rounded-lg border p-2.5 text-xs ${done ? "border-emerald-200 bg-emerald-50/70" : "border-primary/10 bg-background"}`}
          >
            <label className="flex cursor-pointer items-start gap-2">
              <input
                type="checkbox"
                className="mt-0.5 size-4 accent-primary"
                checked={done}
                disabled={
                  !canManage || appointmentSessionSaving === session.id
                }
                onChange={(event) =>
                  void setAppointmentSessionCompletion(
                    appointment,
                    session,
                    event.target.checked,
                  )
                }
              />
              <span className="min-w-0">
                <span className="block truncate text-[10px] font-semibold uppercase tracking-wide text-primary">
                  {serviceName}
                </span>
                <strong>Sessão {session.session_number}</strong> ·{" "}
                {done ? "Concluída" : "Pendente"}
              </span>
            </label>
            {!done ? (
              <div className="mt-2 grid gap-1.5 grid-cols-[1fr_96px_auto]">
                <Input
                  type="date"
                  className="h-8 text-xs"
                  value={draft.date}
                  onChange={(event) =>
                    setAppointmentSessionDrafts((current) => ({
                      ...current,
                      [session.id]: { ...draft, date: event.target.value },
                    }))
                  }
                  disabled={
                    !canManage ||
                    appointmentSessionSaving === `date-${session.id}`
                  }
                />
                <Input
                  type="time"
                  className="h-8 text-xs"
                  value={draft.time}
                  onChange={(event) =>
                    setAppointmentSessionDrafts((current) => ({
                      ...current,
                      [session.id]: { ...draft, time: event.target.value },
                    }))
                  }
                  disabled={
                    !canManage ||
                    appointmentSessionSaving === `date-${session.id}`
                  }
                />
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  className="h-8 px-2 text-[10px]"
                  onClick={() =>
                    void saveAppointmentSessionSchedule(session)
                  }
                  disabled={
                    !canManage ||
                    appointmentSessionSaving === `date-${session.id}`
                  }
                >
                  {appointmentSessionSaving === `date-${session.id}`
                    ? "..."
                    : "Salvar"}
                </Button>
              </div>
            ) : (
              <p className="mt-1.5 text-[11px] text-muted-foreground">
                {session.scheduled_date
                  ? `${dateLabel(session.scheduled_date)}${session.scheduled_time ? ` às ${String(session.scheduled_time).slice(0, 5)}` : ""}`
                  : "Data não informada"}
              </p>
            )}
          </div>
        );
      })}
    </div>
  </div>
)

{row.serviceId ? (
  <div className="sm:col-span-4 rounded-xl bg-primary/[0.04] p-3">
    <p className="text-[11px] font-semibold">Controle das sessões</p>
    <div className="mt-2 flex flex-wrap gap-2">
      {Array.from({ length: sessionCount }, (_, sessionIndex) => (
        <label
          key={sessionIndex}
          className="flex items-center gap-1.5 rounded-lg border bg-background px-2.5 py-1.5 text-xs text-muted-foreground"
        >
          <input type="checkbox" className="size-4" disabled /> Sessão{" "}
          {sessionIndex + 1}
        </label>
      ))}
    </div>
    <p className="mt-2 text-[10px] text-muted-foreground">
      As caixinhas ficam disponíveis para marcar depois que o orçamento
      for salvo.
    </p>
  </div>
)

