                  <div className="mt-3 grid gap-2 sm:grid-cols-2">
                    {(query.data?.appointments ?? []).length === 0 && (query.data?.budgets ?? []).length === 0 ? <div className="sm:col-span-2 rounded-xl border border-dashed p-4 text-center text-xs text-muted-foreground">Nenhum serviço ou combo vinculado ainda.</div> : null}
                    {(query.data?.budgets ?? []).slice(0, 8).map((budget: any) => { const items = [...(budget.client_budget_items ?? [])].sort((a: any,b: any) => Number(a.position)-Number(b.position)); const totalSessions = items.reduce((sum: number,item: any) => sum + Math.max(1,Number(item.sessions)||1),0); const completed = items.reduce((sum: number,item: any) => sum + (Array.isArray(item.completed_session_numbers) ? item.completed_session_numbers.length : 0),0); return <div key={`profile-budget-${budget.id}`} className="rounded-xl border border-primary/15 bg-primary/[0.055] p-3"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="text-xs font-semibold">{budget.title}</p><p className="mt-1 text-[11px] text-muted-foreground">{items.map((item: any) => item.service_name_snapshot).join(" + ")}</p></div><Badge variant={budget.is_paid ? "default" : "secondary"} className={budget.is_paid ? "bg-emerald-600 text-white hover:bg-emerald-600" : ""}>{budget.is_paid ? "Pago" : "Combo"}</Badge></div><p className="mt-2 text-[11px] font-medium text-primary">{completed}/{totalSessions} sessões concluídas · {money(budget.total_amount)}</p></div>; })}
