/* eslint-disable @typescript-eslint/no-explicit-any */
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { CheckCircle2, Clock3, ReceiptText, WalletCards } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";

const db = supabase as any;
const selectClass =
  "h-10 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring";

function money(value: unknown) {
  return Number(value ?? 0).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function parseMoney(value: string) {
  if (!value.trim()) return null;
  const normalized = value.trim().replace(/\./g, "").replace(",", ".");
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : null;
}

function comboItems(appointment: any) {
  return [...(appointment?.appointment_services ?? [])].sort(
    (a: any, b: any) => Number(a.position ?? 0) - Number(b.position ?? 0),
  );
}

function packageSessions(appointment: any) {
  return [...(appointment?.appointment_sessions ?? [])].sort(
    (a: any, b: any) => Number(a.session_number ?? 0) - Number(b.session_number ?? 0),
  );
}

function isPackageAppointment(appointment: any) {
  const items = comboItems(appointment);
  if (items.length) {
    return items.some((item: any) => Number(item?.session_count ?? item?.service?.session_count ?? 1) > 1);
  }
  return packageSessions(appointment).length > 1;
}

function dateLabel(value?: string | null) {
  if (!value) return "—";
  return new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR");
}

async function loadCompletionAccess() {
  const { data, error } = await supabase.auth.getUser();
  if (error || !data.user) throw new Error("Sessão expirada.");
  const result = await db
    .from("financial_access")
    .select("role")
    .eq("user_id", data.user.id)
    .eq("is_active", true);
  if (result.error) throw result.error;
  const roles = (result.data ?? []).map((row: any) => String(row.role));
  return {
    allowed: roles.some((role: string) => ["admin", "finance", "reception"].includes(role)),
    roles,
  };
}

async function loadConfirmedAppointments() {
  const [appointments, methods, cash, financialEntries] = await Promise.all([
    db
      .from("appointments")
      .select(
        "id,patient_name,scheduled_date,scheduled_time,status,professional_id,professional_name_snapshot,custom_price,service_price_snapshot,service_id,service:services!appointments_service_id_fkey(name,price),appointment_services(service_id,position,price_snapshot,session_count,status,completed_at,service:services!appointment_services_service_id_fkey(name,price,session_count)),appointment_sessions(id,session_number,scheduled_date,scheduled_time,status,completed_at),professional:professionals(name)",
      )
      .in("status", ["confirmado", "atendido"])
      .order("scheduled_date", { ascending: true })
      .order("scheduled_time", { ascending: true }),
    db
      .from("payment_methods")
      .select("id,code,name,is_cash")
      .eq("is_active", true)
      .order("sort_order"),
    db
      .from("cash_sessions")
      .select("id,business_date,status,opened_at")
      .eq("status", "open")
      .order("opened_at", { ascending: false })
      .limit(1),
    db
      .from("financial_entries")
      .select("appointment_id,status")
      .not("appointment_id", "is", null),
  ]);
  for (const result of [appointments, methods, cash, financialEntries]) if (result.error) throw result.error;
  const alreadyRegistered = new Set(
    (financialEntries.data ?? [])
      .filter((entry: any) => !["cancelled", "refunded"].includes(String(entry.status ?? "")))
      .map((entry: any) => entry.appointment_id),
  );
  return {
    appointments: (appointments.data ?? []).filter((row: any) => {
      if (alreadyRegistered.has(row.id)) return false;
      const sessions = packageSessions(row);
      if (isPackageAppointment(row)) return sessions.length > 0 && sessions.every((session: any) => session.status === "completed");
      return row.status === "confirmado";
    }),
    methods: methods.data ?? [],
    openCash: cash.data?.[0] ?? null,
  };
}

export function FinanceAttendanceCompletion() {
  const queryClient = useQueryClient();
  const access = useQuery({
    queryKey: ["finance-attendance-access"],
    queryFn: loadCompletionAccess,
  });
  const data = useQuery({
    queryKey: ["finance-confirmed-appointments"],
    queryFn: loadConfirmedAppointments,
    enabled: Boolean(access.data?.allowed),
  });
  const [selectedId, setSelectedId] = useState("");
  const [amount, setAmount] = useState("");
  const [received, setReceived] = useState("yes");
  const [method, setMethod] = useState("");
  const [installments, setInstallments] = useState("1");
  const [discountType, setDiscountType] = useState("none");
  const [discountValue, setDiscountValue] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [manualCommission, setManualCommission] = useState("");
  const [manualReason, setManualReason] = useState("");
  const [busy, setBusy] = useState(false);

  const selected = useMemo(
    () => (data.data?.appointments ?? []).find((row: any) => row.id === selectedId) ?? null,
    [data.data?.appointments, selectedId],
  );

  const selectedItems = useMemo(() => comboItems(selected), [selected]);
  const selectedSessions = useMemo(() => packageSessions(selected), [selected]);

  useEffect(() => {
    if (!selected) return;
    const base = Number(
      selected.custom_price ?? selected.service_price_snapshot ?? selected.service?.price ?? 0,
    );
    setAmount(base.toFixed(2).replace(".", ","));
  }, [selected]);

  useEffect(() => {
    if (!method && data.data?.methods?.length) setMethod(data.data.methods[0].code);
  }, [data.data?.methods, method]);

  if (!access.data?.allowed) return null;

  const finalize = async () => {
    if (!selected) {
      toast.error("Selecione um atendimento confirmado.");
      return;
    }
    const parsedAmount = parseMoney(amount);
    const parsedDiscount = discountType === "none" ? 0 : parseMoney(discountValue);
    const parsedCommission = parseMoney(manualCommission);
    const parsedInstallments = Number(installments);
    const isZeroAmount = parsedAmount === 0;
    if (parsedAmount === null || parsedAmount < 0) {
      toast.error("Informe um valor válido para o procedimento.");
      return;
    }
    if (discountType !== "none" && (parsedDiscount === null || parsedDiscount < 0)) {
      toast.error("Informe um desconto válido.");
      return;
    }
    if (
      !Number.isInteger(parsedInstallments) ||
      parsedInstallments < 1 ||
      parsedInstallments > 12
    ) {
      toast.error("Informe uma quantidade de parcelas entre 1 e 12.");
      return;
    }

    if (received === "yes" && parsedAmount > 0 && !method) {
      toast.error("Selecione a forma de pagamento.");
      return;
    }
    if (!isZeroAmount && received === "no" && !dueDate) {
      toast.error("Informe o vencimento do valor a receber.");
      return;
    }
    if (isZeroAmount && parsedCommission !== null && parsedCommission !== 0) {
      toast.error("Atendimento de R$ 0,00 não pode gerar comissão manual.");
      return;
    }
    if (parsedCommission !== null && !manualReason.trim()) {
      toast.error("Informe o motivo do ajuste manual da comissão.");
      return;
    }

    setBusy(true);
    const result = await db.rpc("complete_appointment_financially", {
      _appointment_id: selected.id,
      _original_amount: parsedAmount,
      _payment_received: isZeroAmount ? true : received === "yes",
      _payment_method_code: !isZeroAmount && received === "yes" && parsedAmount > 0 ? method : null,
      _installments: parsedInstallments,
      _discount_type: discountType === "none" ? null : discountType,
      _discount_value: parsedDiscount ?? 0,
      _receivable_due_date: !isZeroAmount && received === "no" ? dueDate : null,
      _manual_commission_amount: isZeroAmount ? null : parsedCommission,
      _manual_commission_reason: isZeroAmount || parsedCommission === null ? null : manualReason.trim(),
    });
    setBusy(false);

    if (result.error) {
      toast.error("Não foi possível finalizar o atendimento.", {
        description: result.error.message,
      });
      return;
    }

    const hasPendingPackageSessions = isPackageAppointment(selected) && selectedSessions.some((item: any) => item.status !== "completed");
    if (isZeroAmount) {
      toast.success("Atendimento de R$ 0,00 finalizado.", {
        description: "Nenhuma nova receita, comissão ou movimentação de caixa foi criada.",
      });
    } else {
      toast.success(hasPendingPackageSessions ? "Pagamento do pacote registrado." : "Atendimento finalizado e enviado ao financeiro.", {
        description: hasPendingPackageSessions ? "As sessões pendentes continuam em andamento na Agenda." : undefined,
      });
    }
    setSelectedId("");
    setDiscountType("none");
    setDiscountValue("");
    setDueDate("");
    setManualCommission("");
    setManualReason("");
    setInstallments("1");
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: ["finance-confirmed-appointments"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-full-v2"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-reception-v2"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-completion"] }),
    ]);
  };

  return (
    <section className="mx-auto w-full max-w-[1540px] px-5 pt-3 sm:px-8 lg:px-10">
      <div className="rounded-[22px] border border-border/80 bg-card p-5 shadow-[0_8px_24px_rgb(15_77_62_/_0.07)] sm:p-6">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <CheckCircle2 className="size-5 text-primary" />
              <h2 className="text-xl font-semibold">Registrar pagamento</h2>
            </div>
            <p className="mt-1 max-w-3xl text-sm text-muted-foreground">
              Registre o pagamento, desconto, fiado e eventual ajuste manual de comissão. Em pacotes,
              o lançamento financeiro só é liberado depois que todas as sessões forem concluídas.
              Se uma sessão for reaberta, o valor sai dos resultados até a conclusão total novamente.
            </p>
          </div>
          <div className="flex gap-2">
            <Badge variant="outline">{data.data?.appointments?.length ?? 0} confirmado(s)</Badge>
            <Badge variant={data.data?.openCash ? "default" : "destructive"}>
              {data.data?.openCash ? "Caixa aberto" : "Caixa fechado"}
            </Badge>
          </div>
        </div>

        <div className="mt-5 grid gap-4 xl:grid-cols-[minmax(260px,1fr)_minmax(0,2fr)]">
          <div>
            <Label>Atendimento confirmado</Label>
            <select
              className={selectClass}
              value={selectedId}
              onChange={(event) => setSelectedId(event.target.value)}
            >
              <option value="">Selecione...</option>
              {(data.data?.appointments ?? []).map((row: any) => (
                <option key={row.id} value={row.id}>
                  {dateLabel(row.scheduled_date)} {String(row.scheduled_time ?? "").slice(0, 5)} ·{" "}
                  {row.patient_name} · {row.service?.name ?? "Serviço"}
                </option>
              ))}
            </select>
            {selected ? (
              <div className="mt-3 rounded-2xl bg-muted/50 p-4 text-sm">
                <strong>{selected.patient_name}</strong>
                <p className="mt-1 text-muted-foreground">
                  {selected.service?.name ?? "Serviço"} ·{" "}
                  {selected.professional?.name ??
                    selected.professional_name_snapshot ??
                    "Profissional"}
                </p>
                <p className="mt-2 font-medium">
                  Valor base:{" "}
                  {money(
                    selected.custom_price ??
                      selected.service_price_snapshot ??
                      selected.service?.price,
                  )}
                </p>
                {selectedItems.length > 1 ? <div className="mt-3 space-y-1.5 border-t border-border/70 pt-3"><span className="text-xs font-semibold">Serviços incluídos</span>{selectedItems.map((item: any) => <div key={item.service_id} className="flex items-center justify-between gap-3 rounded-lg bg-background px-2.5 py-2 text-xs"><span className="min-w-0 truncate">{item.service?.name ?? "Serviço"}</span><strong className="shrink-0">{money(item.price_snapshot ?? item.service?.price)}</strong></div>)}</div> : null}
                {isPackageAppointment(selected) && selectedSessions.length > 0 ? <div className="mt-3 space-y-1.5 border-t border-border/70 pt-3"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold">Sessões do pacote</span><Badge variant="outline">{selectedSessions.filter((item: any) => item.status === "completed").length}/{selectedSessions.length} concluídas</Badge></div>{selectedSessions.map((item: any) => <div key={item.id} className="flex items-center justify-between gap-3 rounded-lg bg-background px-2.5 py-2 text-xs"><span>Sessão {item.session_number} · {item.status === "completed" ? "Concluída" : "Pendente"}</span><span className="text-muted-foreground">{item.scheduled_date ? dateLabel(item.scheduled_date) : "Data a definir"}</span></div>)}<p className="text-[11px] font-medium text-primary">O lançamento financeiro é liberado somente após todas as sessões serem concluídas.</p></div> : null}
              </div>
            ) : null}
          </div>

          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            <div>
              <Label>Valor original</Label>
              <Input
                value={amount}
                onChange={(event) => setAmount(event.target.value)}
                placeholder="600,00"
              />
              <p className="mt-1 text-[11px] text-muted-foreground">
                Pode usar 0,00 quando a cliente já tiver pago anteriormente. Nesse caso não é criada uma nova entrada no caixa.
              </p>
            </div>
            <div>
              <Label>Recebeu agora?</Label>
              <select
                className={selectClass}
                value={received}
                onChange={(event) => setReceived(event.target.value)}
              >
                <option value="yes">Sim, recebido</option>
                <option value="no">Não, ficou a receber / fiado</option>
              </select>
            </div>
            {received === "yes" ? (
              <div>
                <Label>Forma de pagamento</Label>
                <Select value={method} onValueChange={setMethod}>
                  <SelectTrigger className="h-10 w-full bg-background">
                    <SelectValue placeholder="Selecione a forma de pagamento" />
                  </SelectTrigger>
                  <SelectContent position="popper" className="z-[120]">
                    {(data.data?.methods ?? []).map((row: any) => (
                      <SelectItem key={row.id} value={row.code}>
                        {row.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <div>
                <Label>Vencimento</Label>
                <Input
                  type="date"
                  value={dueDate}
                  onChange={(event) => setDueDate(event.target.value)}
                />
              </div>
            )}
            <div>
              <Label>Parcelas (1 a 12)</Label>
              <Input
                type="number"
                min="1"
                max="12"
                value={installments}
                onChange={(event) => setInstallments(event.target.value)}
              />
            </div>
            <div>
              <Label>Desconto</Label>
              <select
                className={selectClass}
                value={discountType}
                onChange={(event) => setDiscountType(event.target.value)}
              >
                <option value="none">Sem desconto</option>
                <option value="percent">Percentual (%)</option>
                <option value="amount">Valor (R$)</option>
              </select>
            </div>
            <div>
              <Label>Valor do desconto</Label>
              <Input
                disabled={discountType === "none"}
                value={discountValue}
                onChange={(event) => setDiscountValue(event.target.value)}
                placeholder={discountType === "percent" ? "10" : "50,00"}
              />
            </div>
            <div>
              <Label>Comissão manual (opcional)</Label>
              <Input
                value={manualCommission}
                onChange={(event) => setManualCommission(event.target.value)}
                placeholder="Deixe vazio para regra automática"
              />
            </div>
            <div className="md:col-span-2">
              <Label>Motivo da comissão manual</Label>
              <Input
                disabled={!manualCommission.trim()}
                value={manualReason}
                onChange={(event) => setManualReason(event.target.value)}
                placeholder="Obrigatório somente se houver ajuste manual"
              />
            </div>
          </div>
        </div>

        <div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-border/80 bg-background/45 p-4">
          <div className="flex items-center gap-3 text-sm text-muted-foreground">
            {received === "yes" ? (
              <WalletCards className="size-4" />
            ) : (
              <Clock3 className="size-4" />
            )}
            <span>
              {parseMoney(amount) === 0
                ? "R$ 0,00 será finalizado sem gerar nova receita, comissão ou movimentação de caixa — mesmo com o caixa fechado."
                : received === "yes"
                  ? data.data?.openCash
                    ? "O recebimento será lançado no caixa aberto e no financeiro."
                    : "Abra o caixa antes de concluir um atendimento já recebido."
                  : "Será criada uma conta a receber; a taxa da forma de pagamento será calculada apenas quando o cliente pagar."}
            </span>
          </div>
          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button
              type="button"
              variant="outline"
              disabled={!selected}
              onClick={() => {
                if (!selected) return;
                window.dispatchEvent(new CustomEvent("finance:open-split-payment", { detail: { appointmentId: selected.id } }));
                requestAnimationFrame(() =>
                  document.getElementById("finance-split-payment")?.scrollIntoView({ behavior: "smooth", block: "start" }),
                );
              }}
            >
              Dividir em 2 ou mais formas
            </Button>
            <Button disabled={!selected || busy} onClick={() => void finalize()}>
              <ReceiptText className="mr-2 size-4" />{" "}
              {busy ? "Registrando..." : parseMoney(amount) === 0 ? "Finalizar atendimento R$ 0,00" : "Registrar pagamento no financeiro"}
            </Button>
          </div>
        </div>
      </div>
    </section>
  );
}

/* eslint-disable @typescript-eslint/no-explicit-any */
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  CheckCircle2,
  ChevronDown,
  CircleDollarSign,
  HandCoins,
  UserRoundCheck,
} from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { supabase } from "@/integrations/supabase/client";

const db = supabase as any;

function money(value: unknown) {
  return Number(value ?? 0).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

function parseMoney(value: string) {
  const normalized = value.trim().replace(/\./g, "").replace(",", ".");
  return Number(normalized);
}

function formatDate(value?: string | null) {
  if (!value) return "Data não informada";
  return new Date(value).toLocaleDateString("pt-BR", { timeZone: "America/Fortaleza" });
}

function commissionTypeLabel(type: string) {
  if (type === "percentage") return "Percentual";
  if (type === "fixed_per_patient") return "Valor por paciente";
  return "Manual";
}

function relatedEntry(row: any) {
  return Array.isArray(row?.financial_entry)
    ? (row.financial_entry[0] ?? null)
    : (row?.financial_entry ?? null);
}

function paidAmount(row: any) {
  return Math.max(
    0,
    Number(row?.paid_amount ?? (row?.status === "paid" ? row?.commission_amount : 0) ?? 0),
  );
}

function remainingAmount(row: any) {
  return Math.max(
    0,
    Math.round((Number(row?.commission_amount ?? 0) - paidAmount(row)) * 100) / 100,
  );
}

async function loadCommissions() {
  const { data: authData, error: authError } = await supabase.auth.getUser();
  if (authError || !authData.user) throw new Error("Sessão expirada.");

  const access = await db
    .from("financial_access")
    .select("role")
    .eq("user_id", authData.user.id)
    .eq("is_active", true);
  if (access.error) throw access.error;

  const roles = (access.data ?? []).map((row: any) => String(row.role));
  const allowed = roles.includes("admin") || roles.includes("finance");
  if (!allowed) return { allowed: false, commissions: [], professionals: [] };

  const [commissions, professionals] = await Promise.all([
    db
      .from("professional_commissions")
      .select(
        "id,professional_id,commission_type,percentage,fixed_amount,commission_amount,paid_amount,status,paid_at,created_at,financial_entry:financial_entries(patient_name_snapshot,professional_name_snapshot,service_name_snapshot,occurred_at)",
      )
      .order("created_at", { ascending: false })
      .limit(300),
    db.from("professionals").select("id,name").order("name"),
  ]);

  if (commissions.error) throw commissions.error;
  if (professionals.error) throw professionals.error;

  return {
    allowed: true,
    commissions: commissions.data ?? [],
    professionals: professionals.data ?? [],
  };
}

export function FinanceCommissionPaymentActions() {
  const queryClient = useQueryClient();
  const [amounts, setAmounts] = useState<Record<string, string>>({});
  const [busyId, setBusyId] = useState<string | null>(null);
  const [expandedProfessionals, setExpandedProfessionals] = useState<Set<string>>(
    () => new Set(),
  );
  const query = useQuery({
    queryKey: ["finance-commission-payments-grouped"],
    queryFn: loadCommissions,
  });

  const professionalMap = useMemo(
    () =>
      new Map<string, string>(
        (query.data?.professionals ?? []).map((row: any) => [String(row.id), String(row.name)]),
      ),
    [query.data?.professionals],
  );

  const groups = useMemo(() => {
    const grouped = new Map<string, { professionalId: string; name: string; rows: any[] }>();
    for (const row of query.data?.commissions ?? []) {
      if (remainingAmount(row) <= 0) continue;
      const entry = relatedEntry(row);
      const professionalId = String(row.professional_id ?? "unknown");
      const name =
        entry?.professional_name_snapshot ||
        professionalMap.get(professionalId) ||
        `Profissional ${professionalId.slice(0, 8)}`;
      const current = grouped.get(professionalId) ?? { professionalId, name, rows: [] as any[] };
      current.rows.push(row);
      grouped.set(professionalId, current);
    }
    return [...grouped.values()].sort((a, b) => a.name.localeCompare(b.name, "pt-BR"));
  }, [professionalMap, query.data?.commissions]);

  const commissionSummary = useMemo(() => {
    const rows = query.data?.commissions ?? [];
    const total = rows.reduce((sum: number, row: any) => sum + Number(row.commission_amount ?? 0), 0);
    const paid = rows.reduce((sum: number, row: any) => sum + paidAmount(row), 0);
    return {
      total,
      paid,
      remaining: Math.max(0, Math.round((total - paid) * 100) / 100),
    };
  }, [query.data?.commissions]);

  if (!query.data?.allowed) return null;

  const refresh = async () => {
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: ["finance-commission-payments-grouped"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-full-v2"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-completion-lookups"] }),
      queryClient.invalidateQueries({ queryKey: ["finance-completion-report"] }),
      queryClient.invalidateQueries({ queryKey: ["professional-own-commissions"] }),
    ]);
  };

  const toggleProfessional = (professionalId: string) => {
    setExpandedProfessionals((current) => {
      const next = new Set(current);
      if (next.has(professionalId)) next.delete(professionalId);
      else next.add(professionalId);
      return next;
    });
  };

  const registerPayment = async (row: any, amount: number) => {
    const remaining = remainingAmount(row);
    const value = Math.round(Number(amount) * 100) / 100;
    if (!Number.isFinite(value) || value <= 0) {
      toast.error("Informe um valor maior que zero.");
      return;
    }
    if (value > remaining) {
      toast.error(`O valor não pode ser maior que o restante de ${money(remaining)}.`);
      return;
    }

    const entry = relatedEntry(row);
    const professional =
      entry?.professional_name_snapshot ||
      professionalMap.get(String(row.professional_id)) ||
      "Profissional";
    const confirmed = window.confirm(
      `Confirmar pagamento de ${money(value)} para ${professional}? O valor será lançado automaticamente em Despesas.`,
    );
    if (!confirmed) return;

    setBusyId(String(row.id));
    try {
      const result = await db.rpc("register_commission_payment", {
        _commission_id: row.id,
        _amount: value,
      });
      if (result.error) throw result.error;
      setAmounts((current) => ({ ...current, [row.id]: "" }));
      toast.success(value >= remaining ? "Comissão quitada." : "Pagamento parcial registrado.", {
        description: "O pagamento também foi lançado automaticamente em Despesas.",
      });
      await refresh();
    } catch (error: any) {
      toast.error("Não foi possível registrar o pagamento.", {
        description: error?.message || "Tente novamente.",
      });
    } finally {
      setBusyId(null);
    }
  };

  return (
    <section className="finance-commission-payment-actions hidden mx-auto w-full max-w-[1540px] px-5 pb-8 sm:px-8 lg:px-10">
      <div className="rounded-3xl border border-border bg-card p-5 shadow-soft sm:p-6">
        <div className="flex items-start gap-3">
          <span className="grid size-10 shrink-0 place-items-center rounded-2xl bg-primary-soft text-primary">
            <UserRoundCheck className="size-5" />
          </span>
          <div>
            <h2 className="text-xl font-bold tracking-tight text-foreground">Comissões por profissional</h2>
            <p className="mt-1 text-sm text-muted-foreground">
              Clique no nome do profissional para visualizar as comissões. Registre pagamento total,
              metade ou um valor personalizado. Todo valor pago entra automaticamente em Despesas.
            </p>
          </div>
        </div>

        <div className="mt-5 grid gap-3 sm:grid-cols-3">
          <div className="rounded-2xl border border-border bg-primary-soft/30 px-4 py-3">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Total de comissões</p>
            <p className="mt-1 text-xl font-bold text-foreground">{money(commissionSummary.total)}</p>
          </div>
          <div className="rounded-2xl border border-border bg-background/60 px-4 py-3">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Total pago</p>
            <p className="mt-1 text-xl font-bold text-foreground">{money(commissionSummary.paid)}</p>
          </div>
          <div className="rounded-2xl border border-border bg-background/60 px-4 py-3">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Total restante</p>
            <p className="mt-1 text-xl font-bold text-foreground">{money(commissionSummary.remaining)}</p>
          </div>
        </div>

        <div className="mt-6 space-y-3">
          {query.isLoading ? (
            <p className="text-sm text-muted-foreground">Carregando comissões...</p>
          ) : groups.length ? (
            groups.map((group) => {
              const groupTotal = group.rows.reduce(
                (sum, row) => sum + Number(row.commission_amount ?? 0),
                0,
              );
              const groupPaid = group.rows.reduce((sum, row) => sum + paidAmount(row), 0);
              const groupRemaining = Math.max(0, groupTotal - groupPaid);
              const expanded = expandedProfessionals.has(group.professionalId);
              const contentId = `commission-group-${group.professionalId}`;

              return (
                <article
                  key={group.professionalId}
                  className="overflow-hidden rounded-3xl border border-border bg-background/45"
                >
                  <button
                    type="button"
                    className="flex w-full flex-col gap-2 bg-primary-soft/35 px-4 py-4 text-left transition-colors hover:bg-primary-soft/55 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-inset sm:flex-row sm:items-center sm:justify-between sm:px-5"
                    aria-expanded={expanded}
                    aria-controls={contentId}
                    onClick={() => toggleProfessional(group.professionalId)}
                  >
                    <div className="flex min-w-0 items-center gap-3">
                      <ChevronDown
                        className={`size-4 shrink-0 text-muted-foreground transition-transform duration-200 ${expanded ? "rotate-180" : ""}`}
                      />
                      <div className="min-w-0">
                        <h3 className="truncate font-semibold text-foreground">{group.name}</h3>
                        <p className="mt-0.5 text-xs text-muted-foreground">
                          {expanded
                            ? `${group.rows.length} comissão(ões)`
                            : "Clique para ver as comissões"}
                        </p>
                      </div>
                    </div>
                    <div className="flex flex-wrap items-center gap-3 pl-7 text-xs sm:justify-end sm:pl-0">
                      <span className="rounded-full bg-background/80 px-3 py-1.5">
                        Total <strong className="ml-1 text-sm">{money(groupTotal)}</strong>
                      </span>
                      {expanded ? (
                        <>
                          <span>
                            Pago <strong className="ml-1">{money(groupPaid)}</strong>
                          </span>
                          <span>
                            Restante <strong className="ml-1">{money(groupRemaining)}</strong>
                          </span>
                        </>
                      ) : null}
                    </div>
                  </button>

                  {expanded ? (
                    <div id={contentId} className="divide-y divide-border border-t border-border">
                      {group.rows.map((row: any) => {
                        const entry = relatedEntry(row);
                        const total = Number(row.commission_amount ?? 0);
                        const paid = paidAmount(row);
                        const remaining = remainingAmount(row);
                        const partial = row.status !== "paid" && paid > 0;
                        const busy = busyId === String(row.id);
                        const custom = amounts[row.id] ?? "";
                        return (
                          <div key={row.id} className="p-4 sm:p-5">
                            <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                              <div className="min-w-0">
                                <p className="text-sm font-semibold">
                                  {entry?.patient_name_snapshot || "Paciente não identificado"}
                                </p>
                                <p className="mt-1 text-xs text-muted-foreground">
                                  {entry?.service_name_snapshot || "Serviço não identificado"} ·{" "}
                                  {formatDate(entry?.occurred_at)}
                                </p>
                                <p className="mt-1 text-[11px] text-muted-foreground">
                                  {commissionTypeLabel(row.commission_type)}
                                  {row.commission_type === "percentage" && row.percentage != null
                                    ? ` · ${Number(row.percentage)}%`
                                    : ""}
                                  {row.commission_type === "fixed_per_patient" &&
                                  row.fixed_amount != null
                                    ? ` · ${money(row.fixed_amount)} por paciente`
                                    : ""}
                                </p>
                              </div>

                              <div className="min-w-[250px]">
                                <div className="flex flex-wrap items-center justify-between gap-2 text-xs">
                                  <span>
                                    Total <strong className="ml-1">{money(total)}</strong>
                                  </span>
                                  <span>
                                    Pago <strong className="ml-1">{money(paid)}</strong>
                                  </span>
                                  <span>
                                    Restante <strong className="ml-1">{money(remaining)}</strong>
                                  </span>
                                  <Badge variant={row.status === "paid" ? "default" : "secondary"}>
                                    {row.status === "paid"
                                      ? "Pago"
                                      : partial
                                        ? "Parcial"
                                        : "Pendente"}
                                  </Badge>
                                </div>

                                {row.status === "paid" || remaining <= 0 ? (
                                  <div className="mt-3 flex items-center justify-end gap-2 text-xs text-muted-foreground">
                                    <CheckCircle2 className="size-4 text-primary" />
                                    Quitado{row.paid_at ? ` em ${formatDate(row.paid_at)}` : ""}
                                  </div>
                                ) : (
                                  <div className="mt-3 grid gap-2 sm:grid-cols-[auto_1fr_auto_auto]">
                                    <Button
                                      type="button"
                                      size="sm"
                                      variant="outline"
                                      disabled={busy}
                                      onClick={() => {
                                        const half = Math.max(
                                          0.01,
                                          Math.round((remaining / 2) * 100) / 100,
                                        );
                                        void registerPayment(row, half);
                                      }}
                                    >
                                      <HandCoins className="mr-1.5 size-4" /> Pagar metade
                                    </Button>
                                    <Input
                                      inputMode="decimal"
                                      placeholder="Valor já pago"
                                      value={custom}
                                      disabled={busy}
                                      onChange={(event) =>
                                        setAmounts((current) => ({
                                          ...current,
                                          [row.id]: event.target.value,
                                        }))
                                      }
                                    />
                                    <Button
                                      type="button"
                                      size="sm"
                                      variant="outline"
                                      disabled={busy || !custom.trim()}
                                      onClick={() => void registerPayment(row, parseMoney(custom))}
                                    >
                                      Registrar valor
                                    </Button>
                                    <Button
                                      type="button"
                                      size="sm"
                                      disabled={busy}
                                      onClick={() => void registerPayment(row, remaining)}
                                    >
                                      <CircleDollarSign className="mr-1.5 size-4" /> Quitar restante
                                    </Button>
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  ) : null}
                </article>
              );
            })
          ) : (
            <p className="text-sm text-muted-foreground">Nenhuma comissão registrada.</p>
          )}
        </div>
      </div>
    </section>
  );
}

