    )
    .join("");
  printHtml(
    title,
    `<h1>JR Clinic — ${escapeHtml(title)}</h1><p>Período: ${formatDate(from)} a ${formatDate(to)}</p><table><tr><th>Grupo</th><th>Qtd.</th><th>Faturamento</th><th>Taxas</th><th>Líquido</th><th>Comissões</th><th>Clínica</th><th>Despesas</th><th>Resultado financeiro</th></tr>${tableRows}</table>`,
  );
}

function printCash(row: any) {
  printHtml(
    `Fechamento de caixa ${formatDate(row.business_date)}`,
    `<h1>JR Clinic — Fechamento de Caixa</h1><p>Data: ${formatDate(row.business_date)}</p><div class="grid"><div class="box">Aberto por<div class="value">${escapeHtml(row.opened_by_label || row.opened_by)}</div><small>${formatDateTime(row.opened_at)}</small></div><div class="box">Fechado por<div class="value">${escapeHtml(row.closed_by_label || row.closed_by || "—")}</div><small>${formatDateTime(row.closed_at)}</small></div><div class="box">Status<div class="value">${escapeHtml(row.status)}</div></div></div><table><tr><th>Fundo inicial</th><th>Dinheiro</th><th>Pix</th><th>Débito</th><th>Crédito</th><th>Link</th><th>Saídas dinheiro</th></tr><tr><td>${money(row.opening_cash)}</td><td>${money(row.total_cash)}</td><td>${money(row.total_pix)}</td><td>${money(row.total_debit)}</td><td>${money(row.total_credit)}</td><td>${money(row.total_link)}</td><td>${money(row.total_cash_expenses)}</td></tr></table><div class="grid"><div class="box">Esperado em espécie<div class="value">${money(row.expected_cash)}</div></div><div class="box">Contado<div class="value">${money(row.counted_cash)}</div></div><div class="box">Diferença<div class="value">${money(row.difference_amount)}</div></div></div><p><strong>Observação:</strong> ${escapeHtml(row.closing_note || "Sem observação")}</p>`,
  );
}

function printSettlement(row: any, professionalName: string) {
  printHtml(
    `Fechamento profissional ${professionalName}`,
    `<h1>JR Clinic — Fechamento por Profissional</h1><p>${escapeHtml(professionalName)} · ${formatDate(row.period_start)} a ${formatDate(row.period_end)}</p><div class="grid"><div class="box">Atendimentos<div class="value">${escapeHtml(row.procedures_count)}</div></div><div class="box">Faturamento bruto<div class="value">${money(row.gross_revenue)}</div></div><div class="box">Faturamento líquido<div class="value">${money(row.net_revenue)}</div></div><div class="box">Comissão<div class="value">${money(row.commission_total)}</div></div><div class="box">Parte da clínica<div class="value">${money(row.clinic_total)}</div></div><div class="box">Pendente<div class="value">${money(row.amount_pending)}</div></div></div><table><tr><th>Já repassado</th><th>Pendente</th><th>Status</th></tr><tr><td>${money(row.amount_repassed)}</td><td>${money(row.amount_pending)}</td><td>${escapeHtml(row.status)}</td></tr></table>`,
  );
}

export function FinanceCompletionSuite() {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState(monthStartIso());
  const [to, setTo] = useState(fortalezaIso());
  const [section, setSection] = useState("month");
  const [professional, setProfessional] = useState("");
  const [service, setService] = useState("");
  const [method, setMethod] = useState("");
  const [category, setCategory] = useState("");
  const [center, setCenter] = useState("");
  const [status, setStatus] = useState("");
  const [cashDate, setCashDate] = useState(fortalezaIso());
  const [savingService, setSavingService] = useState("");

  const access = useQuery({ queryKey: ["finance-completion-access"], queryFn: loadAccess });
  const lookups = useQuery({
    queryKey: ["finance-completion-lookups"],
    queryFn: loadLookups,
    enabled: Boolean(access.data?.full),
  });
  const report = useQuery({
    queryKey: [
      "finance-completion-report",
      from,
      to,
      professional,
      service,
      method,
      category,
      center,
      status,
    ],
    queryFn: () =>
      loadReport({ from, to, professional, service, method, category, center, status }),
    enabled: Boolean(access.data?.full && from && to),
  });
  const cash = useQuery({
    queryKey: ["finance-cash-by-date", cashDate],
    queryFn: () => loadCashByDate(cashDate),
    enabled: Boolean(access.data?.full && cashDate),
  });
  const cashRange = useQuery({
    queryKey: ["finance-cash-range", from, to],
    queryFn: () => loadCashRange(from, to),
    enabled: Boolean(access.data?.full && from && to),
  });

  const professionals = useMemo(() => {
    const map = new Map<string, string>();
    for (const row of lookups.data?.entries ?? []) {
      if (row.professional_id) {
        map.set(row.professional_id, row.professional_name_snapshot || "Profissional");
      }
    }
    return [...map.entries()].map(([id, name]) => ({ id, name }));
  }, [lookups.data?.entries]);

  const professionalMap = useMemo(
    () => new Map(professionals.map((item) => [item.id, item.name])),
    [professionals],
  );
  const mappingMap = useMemo(
    () =>
      new Map<string, string>(
        (lookups.data?.mappings ?? []).map((row: any) => [row.service_id, row.cost_center_id]),
      ),
    [lookups.data?.mappings],
  );
  const selectedRows = (report.data ?? []).filter((row: any) => row.section === section);
  const centerRows = (report.data ?? []).filter((row: any) => row.section === "cost_center");
  const sectionTitle = reportSections.find(([value]) => value === section)?.[1] ?? "Relatório";
  const cashMethodId = (lookups.data?.methods ?? []).find((item: any) => item.code === "cash")?.id ?? "";
  const cashFilterActive = Boolean(method && cashMethodId && method === cashMethodId);
  const cashRows = cashRange.data ?? [];
  const cashTotals = useMemo(() => {
    const rows = cashRange.data ?? [];
    const closed = rows.filter((row: any) => row.status === "closed");
    const open = rows.filter((row: any) => row.status === "open");
    return {
      sessions: rows.length,
      cashIn: rows.reduce((sum: number, row: any) => sum + Number(row.total_cash ?? 0), 0),
      cashOut: rows.reduce((sum: number, row: any) => sum + Number(row.total_cash_expenses ?? 0), 0),
      cashResult: rows.reduce((sum: number, row: any) => sum + Number(row.cash_result ?? (Number(row.total_cash ?? 0) - Number(row.total_cash_expenses ?? 0))), 0),
      difference: closed.reduce((sum: number, row: any) => sum + Number(row.difference_amount ?? 0), 0),
      openExpected: open.reduce((sum: number, row: any) => sum + Number(row.expected_cash ?? 0), 0),
      closed: closed.length,
      open: open.length,
    };
  }, [cashRange.data]);
  const reportCashResult = cashFilterActive
    ? selectedRows.reduce((sum: number, row: any) => sum + Number(row.result_amount ?? 0), 0)
    : null;
  const reconciliationGap = reportCashResult == null ? null : reportCashResult - cashTotals.cashResult;

  const saveServiceCenter = async (serviceId: string, costCenterId: string) => {
    if (!access.data?.user) return;
    setSavingService(serviceId);
    try {
      if (!costCenterId) {
        const result = await db.from("service_cost_centers").delete().eq("service_id", serviceId);
        if (result.error) throw result.error;
      } else {
        const result = await db.from("service_cost_centers").upsert(
          {
            service_id: serviceId,
            cost_center_id: costCenterId,
            created_by: access.data.user.id,
          },
          { onConflict: "service_id" },
        );
        if (result.error) throw result.error;
      }
      toast.success("Área do serviço atualizada.");
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: ["finance-completion-lookups"] }),
        queryClient.invalidateQueries({ queryKey: ["finance-completion-report"] }),
        queryClient.invalidateQueries({ queryKey: ["finance-full-v2"] }),
      ]);
    } catch (error: any) {
      toast.error("Não foi possível atualizar a área.", { description: error?.message });
    } finally {
      setSavingService("");
    }
  };

  if (!access.data?.full) return null;

  return (
    <section className="mx-auto max-w-[1500px] px-5 pb-12 lg:px-8">
      <div className="mb-5 mt-2 flex flex-wrap items-center justify-between gap-3 rounded-3xl border border-border bg-card p-5 shadow-soft">
        <div>
          <div className="flex items-center gap-2">
            <Building2 className="size-4 text-primary" />
            <h2 className="text-xl font-bold tracking-tight text-foreground">Complementos do financeiro</h2>
          </div>
          <p className="mt-1 text-sm text-muted-foreground">
            Alertas, relatórios completos, áreas da clínica e PDFs de fechamento.
          </p>
        </div>
        <Button
          variant="outline"
          onClick={() => {
            void queryClient.invalidateQueries({ queryKey: ["finance-completion"] });
            void lookups.refetch();
            void report.refetch();
            void cash.refetch();
            void cashRange.refetch();
          }}
        >
          <RefreshCw className="mr-2 size-4" /> Atualizar
        </Button>
      </div>

      <div className="grid gap-5 xl:grid-cols-2">
        <AlertList
          title="Contas a pagar — alertas"
          rows={lookups.data?.payables ?? []}
          kind="pay"
        />
        <AlertList
          title="Contas a receber — alertas"
          rows={lookups.data?.receivables ?? []}
          kind="receive"
        />
      </div>

      <section className="mt-5 rounded-3xl border border-border bg-card p-5 shadow-soft">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h3 className="text-xl font-bold tracking-tight text-foreground">Relatórios financeiros completos</h3>
            <p className="mt-1 text-sm text-muted-foreground">
              Use os filtros combinados e gere Excel ou PDF do resultado exibido.
            </p>
          </div>
          <div className="flex gap-2">
            <Button
              variant="outline"
              disabled={!selectedRows.length}
              onClick={() => exportReport(selectedRows, sectionTitle, from, to)}
            >
              <FileSpreadsheet className="mr-2 size-4" /> Excel
            </Button>
            <Button
              variant="outline"
              disabled={!selectedRows.length}
              onClick={() => printReport(selectedRows, sectionTitle, from, to)}
            >
              <FileText className="mr-2 size-4" /> PDF
            </Button>
          </div>
        </div>

        <div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
          <div>
            <Label>De</Label>
            <Input type="date" value={from} onChange={(event) => setFrom(event.target.value)} />
          </div>
          <div>
            <Label>Até</Label>
            <Input type="date" value={to} onChange={(event) => setTo(event.target.value)} />
          </div>
          <div>
            <Label>Tipo de relatório</Label>
            <select
              className={selectClass}
              value={section}
              onChange={(event) => setSection(event.target.value)}
            >
              {reportSections.map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>
          <div>
            <Label>Status</Label>
            <select
              className={selectClass}
              value={status}
              onChange={(event) => setStatus(event.target.value)}
            >
              <option value="">Todos</option>
              <option value="received">Recebido</option>
              <option value="pending">Pendente</option>
              <option value="paid">Pago</option>
              <option value="refunded">Estornado</option>
            </select>
          </div>
          <select
            className={selectClass}
            value={professional}
            onChange={(event) => setProfessional(event.target.value)}
          >
            <option value="">Todos os profissionais</option>
            {professionals.map((item) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <select
            className={selectClass}
            value={service}
            onChange={(event) => setService(event.target.value)}
          >
            <option value="">Todos os serviços</option>
            {(lookups.data?.services ?? []).map((item: any) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <select
            className={selectClass}
            value={method}
            onChange={(event) => setMethod(event.target.value)}
          >
            <option value="">Todas as formas de pagamento</option>
            {(lookups.data?.methods ?? []).map((item: any) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <select
            className={selectClass}
            value={category}
            onChange={(event) => setCategory(event.target.value)}
          >
            <option value="">Todas as categorias de despesa</option>
            {(lookups.data?.categories ?? []).map((item: any) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <select
            className={selectClass}
            value={center}
            onChange={(event) => setCenter(event.target.value)}
          >
            <option value="">Todas as áreas</option>
            {(lookups.data?.centers ?? []).map((item: any) => (
              <option key={item.id} value={item.id}>
                {item.name}
              </option>
            ))}
          </select>
          <Button
            variant="ghost"
            onClick={() => {
              setProfessional("");
              setService("");
              setMethod("");
              setCategory("");
              setCenter("");
              setStatus("");
            }}
          >
            Limpar filtros
          </Button>
        </div>

        <div className="mt-5 overflow-x-auto rounded-2xl border border-border">
          <table className="w-full min-w-[920px] text-sm">
            <thead className="bg-muted/60 text-left text-xs text-muted-foreground">
              <tr>
                <th className="p-3">Grupo</th>
                <th className="p-3">Qtd.</th>
                <th className="p-3">Faturamento</th>
                <th className="p-3">Taxas</th>
                <th className="p-3">Líquido</th>
                <th className="p-3">Comissões</th>
                <th className="p-3">Clínica</th>
                <th className="p-3">Despesas</th>
                <th className="p-3">{cashFilterActive ? "Saldo atual em dinheiro" : "Resultado financeiro"}</th>
              </tr>
            </thead>
            <tbody>
              {selectedRows.map((row: any) => (
                <tr key={`${row.section}-${row.report_key}`} className="border-t border-border">
                  <td className="p-3 font-medium">{row.label}</td>
                  <td className="p-3">{row.quantity}</td>
                  <td className="p-3">{money(row.gross_amount)}</td>
                  <td className="p-3">{money(row.fee_amount)}</td>
                  <td className="p-3">{money(row.net_amount)}</td>
                  <td className="p-3">{money(row.commission_amount)}</td>
                  <td className="p-3">{money(row.clinic_amount)}</td>
                  <td className="p-3">{money(row.expense_amount)}</td>
                  <td className="p-3 font-semibold">{cashFilterActive ? money(cashTotals.open > 0 ? cashTotals.openExpected : cashTotals.cashResult) : money(row.result_amount)}</td>
                </tr>
              ))}
              {!selectedRows.length ? (
                <tr>
                  <td colSpan={9} className="p-6 text-center text-muted-foreground">
                    {report.isLoading
                      ? "Carregando relatório..."
                      : "Nenhum dado para os filtros selecionados."}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>

        {(method === "" || cashFilterActive) ? (
          <div className="mt-5 rounded-2xl border border-primary/15 bg-primary/[0.035] p-4 sm:p-5">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <h4 className="font-semibold text-foreground">Conciliação com abertura e fechamento de caixa</h4>
                <p className="mt-1 max-w-3xl text-xs text-muted-foreground">
                  Resultado financeiro e dinheiro físico em caixa são informações diferentes. O fundo inicial não entra no faturamento; para saber quanto deve existir fisicamente, consulte <strong>Caixa esperado agora</strong>.
                </p>
              </div>
              <Badge variant="secondary">{cashTotals.sessions} caixa(s) no período</Badge>
            </div>

            <div className="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-6">
              {cashFilterActive ? (
                <div className="rounded-xl border border-primary/25 bg-primary/[0.06] p-3">
                  <span className="text-[11px] font-medium text-foreground">Saldo atual em dinheiro</span>
                  <strong className="mt-1 block text-lg">{money(cashTotals.open > 0 ? cashTotals.openExpected : cashTotals.cashResult)}</strong>
                  <p className="mt-1 text-[10px] text-muted-foreground">Inclui o fundo de abertura + entradas em dinheiro − saídas em dinheiro.</p>
                </div>
              ) : null}
              {cashTotals.open > 0 ? (
                <div className="rounded-xl border border-primary/25 bg-primary/[0.06] p-3">
                  <span className="text-[11px] font-medium text-foreground">Caixa esperado agora</span>
                  <strong className="mt-1 block text-lg">{money(cashTotals.openExpected)}</strong>
                  <p className="mt-1 text-[10px] text-muted-foreground">Inclui fundo inicial + entradas em dinheiro − saídas em dinheiro.</p>
                </div>
              ) : null}
              <div className="rounded-xl border border-border bg-card p-3">
                <span className="text-[11px] text-muted-foreground">Entradas em dinheiro</span>
                <strong className="mt-1 block">{money(cashTotals.cashIn)}</strong>
              </div>
              <div className="rounded-xl border border-border bg-card p-3">
                <span className="text-[11px] text-muted-foreground">Saídas em dinheiro</span>
                <strong className="mt-1 block">{money(cashTotals.cashOut)}</strong>
              </div>
              <div className="rounded-xl border border-border bg-card p-3">
                <span className="text-[11px] text-muted-foreground">Movimento do caixa (sem abertura)</span>
                <strong className="mt-1 block">{money(cashTotals.cashResult)}</strong>
              </div>
              <div className="rounded-xl border border-border bg-card p-3">
                <span className="text-[11px] text-muted-foreground">Sobra / falta em caixas já fechados</span>
                <strong className={`mt-1 block ${Math.abs(cashTotals.difference) > 0.01 ? "text-destructive" : ""}`}>{money(cashTotals.difference)}</strong>
              </div>
            </div>

            {!cashFilterActive && method === "" ? (
              <p className="mt-3 text-[11px] text-muted-foreground">
                Para analisar apenas dinheiro, selecione <strong>Dinheiro</strong> em Forma de pagamento. O saldo físico do caixa continua sendo mostrado separadamente em <strong>Caixa esperado agora</strong>.
              </p>
            ) : null}

            <div className="mt-4 overflow-x-auto rounded-xl border border-border bg-card">
              <table className="w-full min-w-[980px] text-xs">
                <thead className="bg-muted/60 text-left text-muted-foreground">
                  <tr>
                    <th className="p-2.5">Data</th>
                    <th className="p-2.5">Status</th>
                    <th className="p-2.5">Abertura</th>
                    <th className="p-2.5">Entradas dinheiro</th>
                    <th className="p-2.5">Saídas dinheiro</th>
                    <th className="p-2.5">Movimento em dinheiro</th>
                    <th className="p-2.5">Esperado no caixa (com abertura)</th>
                    <th className="p-2.5">Contado</th>
                    <th className="p-2.5">Sobra / falta</th>
                  </tr>
                </thead>
                <tbody>
                  {cashRows.map((row: any) => (
                    <tr key={row.cash_session_id ?? row.id} className={`border-t border-border ${row.status === "open" ? "bg-primary/[0.035]" : ""}`}>
