export type AppointmentContactData = {
  patient_name?: string | null;
  patient_phone?: string | null;
  scheduled_date?: string | null;
  scheduled_time?: string | null;
  service_price_snapshot?: number | string | null;
  service?: { name?: string | null; price?: number | string | null } | null;
  professional?: { name?: string | null } | null;
};

function localDateFromIso(value?: string | null) {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [yearStr, monthStr, dayStr] = value.split("-");
  const year = Number(yearStr);
  const month = Number(monthStr);
  const day = Number(dayStr);
  return new Date(year, month - 1, day, 12, 0, 0, 0);
}

export function daysUntilAppointment(value?: string | null) {
  const target = localDateFromIso(value);
  if (!target) return null;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12, 0, 0, 0);
  return Math.round((target.getTime() - today.getTime()) / 86_400_000);
}

export function appointmentProximity(value?: string | null) {
  const days = daysUntilAppointment(value);
  if (days === null || days < 0) return "past" as const;
  if (days <= 1) return "urgent" as const;
  if (days <= 3) return "soon" as const;
  return "normal" as const;
}

export function normalizeWhatsAppPhone(value?: string | null) {
  const digits = String(value ?? "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("55") && digits.length >= 12) return digits;
  if (digits.length === 10 || digits.length === 11) return `55${digits}`;
  return digits;
}

function formatMoney(value: number) {
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
}

function formatAppointmentDate(value?: string | null) {
  const date = localDateFromIso(value);
  if (!date) return "data não informada";
  const weekday = new Intl.DateTimeFormat("pt-BR", { weekday: "long" }).format(date);
  const dateLabel = new Intl.DateTimeFormat("pt-BR").format(date);
  return `${weekday}, ${dateLabel}`;
}

export function appointmentWhatsAppMessage(appointment: AppointmentContactData, kind: "confirmation" | "reminder" | "chat") {
  const total = Number(appointment.service_price_snapshot ?? appointment.service?.price ?? 0);
  if (kind === "chat") {
    return `Olá, ${appointment.patient_name ?? "cliente"}! Tudo bem?`;
  }

  const days = daysUntilAppointment(appointment.scheduled_date);
  const reminderIntro =
    days === 0
      ? "Passando para lembrar que seu atendimento na JR Clinic é hoje."
      : days === 1
        ? "Passando para lembrar que seu atendimento na JR Clinic é amanhã."
        : days !== null && days > 1
          ? `Passando para lembrar do seu atendimento na JR Clinic, agendado para daqui a ${days} dias.`
          : "Passando para lembrar do seu atendimento agendado na JR Clinic.";

  const lines = kind === "reminder"
    ? [
        `Olá, ${appointment.patient_name ?? "cliente"}! Tudo bem?`,
        reminderIntro,
      ]
    : [
        `Olá, ${appointment.patient_name ?? "cliente"}! Tudo bem?`,
        "Estamos entrando em contato para confirmar os dados do seu agendamento na JR Clinic:",
      ];

  lines.push(
    "",
    `Data: ${formatAppointmentDate(appointment.scheduled_date)}`,
    `Horário: ${appointment.scheduled_time ?? "não informado"}`,
    `Profissional: ${appointment.professional?.name ?? "JR Clinic"}`,
    `Serviço: ${appointment.service?.name ?? "Atendimento"}`,
    `Valor: ${formatMoney(Number.isFinite(total) ? total : 0)}`,
    "",
    kind === "reminder"
      ? "Pode confirmar, por favor, se está tudo certo para o seu atendimento?"
      : "Pode confirmar por aqui se está tudo certo com o seu horário?",
  );

  return lines.join("\n");
}

export function appointmentWhatsAppUrl(appointment: AppointmentContactData, kind: "confirmation" | "reminder" | "chat") {
  const phone = normalizeWhatsAppPhone(appointment.patient_phone);
  if (!phone) return null;
  return `https://wa.me/${phone}?text=${encodeURIComponent(appointmentWhatsAppMessage(appointment, kind))}`;
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";

import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

function money(value: number) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

const whatsappSchema = z
  .string()
  .trim()
  .min(10, "Informe seu WhatsApp.")
  .max(40)
  .refine((value) => {
    const digits = value.replace(/\D/g, "");
    return digits.length >= 10 && digits.length <= 15;
  }, "Informe um número de WhatsApp válido com DDD.");

export const createBookingAppointment = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((data) =>
    z
      .object({
        serviceId: z.string().uuid(),
        professionalId: z.string().uuid(),
        patientName: z.string().trim().min(2).max(120),
        patientEmail: z.string().trim().email(),
        patientPhone: whatsappSchema,
        notes: z.string().trim().max(1000).optional().default(""),
        scheduledDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
        scheduledTime: z.string().regex(/^\d{2}:\d{2}$/),
        paymentChoice: z.enum(["deposit", "full", "onsite"]),
      })
      .parse(data),
  )
  .handler(async ({ data, context }) => {
    const db = context.supabase as any;

    const [{ data: validLink, error: linkError }, serviceResult, settingsResult] = await Promise.all([
      db
        .from("service_professionals")
        .select("service_id")
        .eq("service_id", data.serviceId)
        .eq("professional_id", data.professionalId)
        .maybeSingle(),
      db.from("services").select("id, price, is_active").eq("id", data.serviceId).maybeSingle(),
      db.from("business_settings").select("online_deposit_percent").eq("id", 1).maybeSingle(),
    ]);

    if (linkError) throw linkError;
    if (!validLink) throw new Error("Esse profissional não atende o serviço selecionado.");
    if (serviceResult.error) throw serviceResult.error;
    if (!serviceResult.data?.is_active) throw new Error("Esse serviço não está disponível no momento.");
    if (settingsResult.error) throw settingsResult.error;

    const total = money(Number(serviceResult.data.price ?? 0));
    if (!Number.isFinite(total) || total < 0.01) {
      throw new Error("O serviço precisa ter valor mínimo de R$ 0,01.");
    }

    const rawDepositPercent = Number(settingsResult.data?.online_deposit_percent ?? 50);
    const depositPercent = Math.max(1, Math.min(100, Number.isFinite(rawDepositPercent) ? rawDepositPercent : 50));
    const configuredDeposit = Math.min(total, Math.max(0.01, money(total * depositPercent / 100)));

    const isDeposit = data.paymentChoice === "deposit";
    const isFull = data.paymentChoice === "full";
    const requiresOnlinePayment = isDeposit || isFull;

    const paymentAmount = isDeposit ? configuredDeposit : isFull ? total : 0;
    const depositAmount = isDeposit ? configuredDeposit : isFull ? configuredDeposit : 0;
    const balanceAmount = isDeposit ? money(Math.max(0, total - configuredDeposit)) : isFull ? 0 : total;
    const paymentChoice = isDeposit ? "online_deposit" : isFull ? "online_full" : "onsite";

    const { data: created, error } = await db
      .from("appointments")
      .insert({
        user_id: context.userId,
        service_id: data.serviceId,
        professional_id: data.professionalId,
        patient_name: data.patientName,
        patient_email: data.patientEmail,
        patient_phone: data.patientPhone,
        notes: data.notes,
        scheduled_date: data.scheduledDate,
        scheduled_time: data.scheduledTime,
        status: requiresOnlinePayment ? "aguardando_pagamento" : "pendente",
        payment_choice: paymentChoice,
        service_price_snapshot: total,
        deposit_percent: depositPercent,
        deposit_amount: depositAmount,
        balance_amount: balanceAmount,
      })
      .select("id")
      .single();

    if (error) throw error;

    return {
      id: created.id,
      total,
      depositPercent,
      depositAmount,
      balanceAmount,
      paymentAmount,
      paymentChoice: data.paymentChoice,
      paymentKind: isFull ? ("full" as const) : ("deposit" as const),
      requiresOnlinePayment,
    };
  });

