function money(value: number) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function publicClient() {
  return createClient<Database>(
    JR_CLINIC_SUPABASE_URL,
    JR_CLINIC_SUPABASE_PUBLISHABLE_KEY,
