}

function ServiceEditor({
  service,
  categories,
  professionals,
  serviceProfessionalLinks,
  onSaved,
}: any) {
  const linkedProfessionalIds = service?.id
    ? (serviceProfessionalLinks ?? [])
        .filter((link: any) => link.service_id === service.id)
        .map((link: any) => link.professional_id)
    : [];
  const fallbackProfessionalIds =
    linkedProfessionalIds.length > 0 || !service?.professional
      ? linkedProfessionalIds
      : (professionals ?? [])
          .filter((item: any) => service.professional.includes(item.name))
          .map((item: any) => item.id);

  const [open, setOpen] = useState(false);
  const [name, setName] = useState(service?.name ?? "");
  const [categoryId, setCategoryId] = useState(service?.category_id ?? categories[0]?.id ?? "");
  const [selectedProfessionalIds, setSelectedProfessionalIds] =
    useState<string[]>(fallbackProfessionalIds);
  const [duration, setDuration] = useState(String(service?.duration_min ?? 30));
  const [sessionCount, setSessionCount] = useState(String(service?.session_count ?? 1));
  const [price, setPrice] = useState(String(service?.price ?? ""));
  const [summary, setSummary] = useState(service?.summary ?? "");
  const [descriptionText, setDescriptionText] = useState(service?.description ?? "");
  const [busy, setBusy] = useState(false);

  const toggleProfessional = (professionalId: string, checked: boolean) => {
    setSelectedProfessionalIds((current) =>
      checked
        ? current.includes(professionalId)
          ? current
          : [...current, professionalId]
        : current.filter((id) => id !== professionalId),
    );
  };

  const save = async () => {
    if (!name.trim() || !categoryId || !price) {
      toast.error("Preencha nome, categoria e valor.");
      return;
    }
    if (selectedProfessionalIds.length === 0) {
      toast.error("Selecione pelo menos um profissional para este serviço.");
      return;
    }

    setBusy(true);
    const selectedProfessionals = (professionals ?? []).filter((item: any) =>
      selectedProfessionalIds.includes(item.id),
    );
    const professionalNames = selectedProfessionals.map((item: any) => item.name).join(", ");
    const professionalRoles = [
      ...new Set(selectedProfessionals.map((item: any) => item.specialty).filter(Boolean)),
    ].join(" · ");

    const payload = {
      name: name.trim(),
      slug: service?.slug ?? slugify(name),
      category_id: categoryId,
      professional: professionalNames,
      professional_role: professionalRoles,
      duration_min: Number(duration) || 30,
      session_count: Math.min(50, Math.max(1, Number(sessionCount) || 1)),
      price: Number(price.replace(",", ".")) || 0,
      summary: summary.trim(),
      description: descriptionText.trim(),
      includes: service?.includes ?? [],
      preparation: service?.preparation ?? [],
      is_active: service?.is_active ?? true,
    };

    let serviceId = service?.id as string | undefined;
    if (serviceId) {
      const { error: serviceError } = await db.from("services").update(payload).eq("id", serviceId);
      if (serviceError) {
        setBusy(false);
        toast.error(serviceError.message);
        return;
      }
    } else {
      const { data: created, error: serviceError } = await db
        .from("services")
        .insert(payload)
        .select("id")
        .single();
      if (serviceError || !created?.id) {
        setBusy(false);
        toast.error(serviceError?.message ?? "Não foi possível criar o serviço.");
        return;
      }
      serviceId = created.id;
    }

    const linkRows = selectedProfessionalIds.map((professionalId) => ({
      service_id: serviceId,
      professional_id: professionalId,
    }));
    const { error: linkError } = await db
      .from("service_professionals")
      .upsert(linkRows, { onConflict: "service_id,professional_id" });

    if (linkError) {
      if (!service?.id && serviceId) await db.from("services").delete().eq("id", serviceId);
      setBusy(false);
      toast.error(
        `Serviço salvo, mas não foi possível vincular o profissional: ${linkError.message}`,
      );
      return;
    }

    const removedProfessionalIds = linkedProfessionalIds.filter(
      (professionalId: string) => !selectedProfessionalIds.includes(professionalId),
    );
    if (removedProfessionalIds.length > 0 && serviceId) {
      const { error: unlinkError } = await db
        .from("service_professionals")
        .delete()
        .eq("service_id", serviceId)
        .in("professional_id", removedProfessionalIds);
      if (unlinkError) {
        setBusy(false);
        toast.error(
          `Serviço salvo, mas um vínculo antigo não pôde ser removido: ${unlinkError.message}`,
        );
        return;
      }
    }

    setBusy(false);
    toast.success(service?.id ? "Serviço atualizado." : "Serviço criado e vinculado à equipe.");
    setOpen(false);

    if (!service?.id) {
      setName("");
      setCategoryId(categories[0]?.id ?? "");
      setSelectedProfessionalIds([]);
      setDuration("30");
      setSessionCount("1");
      setPrice("");
      setSummary("");
      setDescriptionText("");
    }

    onSaved();
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {service ? (
          <Button
            variant="ghost"
            size="icon"
            className="size-8 rounded-lg sm:size-9"
            aria-label={`Editar ${service.name}`}
          >
            <Pencil className="size-3.5 sm:size-4" />
          </Button>
        ) : (
          <Button size="sm" className="h-9 rounded-full px-3 text-xs sm:h-10 sm:px-4 sm:text-sm">
            <Plus className="size-3.5 sm:size-4" /> <span className="sm:hidden">Novo</span>
            <span className="hidden sm:inline">Novo serviço</span>
          </Button>
        )}
      </DialogTrigger>
      <DialogContent className="max-h-[92dvh] w-[calc(100%-1rem)] overflow-y-auto rounded-2xl p-5 sm:max-w-2xl sm:p-6">
        <DialogHeader>
          <DialogTitle>{service ? "Editar serviço" : "Novo serviço"}</DialogTitle>
          <DialogDescription>
            Preencha os dados abaixo. O profissional selecionado também será disponibilizado na
            etapa de agendamento.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-2 sm:grid-cols-2">
          <Field label="Nome do serviço" hint="Nome que o cliente verá no catálogo.">
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Ex.: Limpeza dental"
            />
          </Field>
          <Field label="Categoria" hint="Define em qual seção do catálogo o serviço aparece.">
            <Select value={categoryId} onValueChange={setCategoryId}>
              <SelectTrigger>
                <SelectValue placeholder="Selecione a categoria" />
              </SelectTrigger>
              <SelectContent>
                {categories.map((c: any) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>

          <div className="sm:col-span-2">
            <Field
              label="Profissionais que realizam este serviço"
              hint="Selecione uma ou mais profissionais cadastradas. Elas serão as opções disponíveis para o cliente no agendamento."
            >
              <div className="grid gap-2 sm:grid-cols-2">
                {(professionals ?? []).length === 0 ? (
                  <div className="sm:col-span-2 rounded-xl border border-dashed border-border bg-secondary/30 px-4 py-3 text-xs text-muted-foreground">
                    Nenhum profissional cadastrado. Cadastre a equipe antes de criar o serviço.
                  </div>
                ) : (
                  (professionals ?? []).map((item: any) => {
                    const checked = selectedProfessionalIds.includes(item.id);
                    return (
                      <label
                        key={item.id}
                        className={`flex cursor-pointer items-start gap-3 rounded-xl border p-3 transition-colors ${
                          checked
                            ? "border-primary bg-primary-soft/60"
                            : "border-border bg-background hover:bg-secondary/40"
                        } ${item.is_active ? "" : "opacity-60"}`}
                      >
                        <Checkbox
                          checked={checked}
                          onCheckedChange={(value) => toggleProfessional(item.id, value === true)}
                          className="mt-0.5"
                        />
                        <span className="min-w-0">
                          <span className="block truncate text-sm font-medium">{item.name}</span>
                          <span className="mt-0.5 block text-[11px] text-muted-foreground">
                            {item.specialty || "Profissional da clínica"}
                            {item.is_active ? "" : " · inativo"}
                          </span>
                        </span>
                      </label>
                    );
                  })
                )}
              </div>
              {selectedProfessionalIds.length > 0 ? (
                <p className="mt-2 text-[11px] font-medium text-primary">
                  {selectedProfessionalIds.length} profissional
                  {selectedProfessionalIds.length > 1 ? "is" : ""} selecionado
                  {selectedProfessionalIds.length > 1 ? "s" : ""}.
                </p>
              ) : null}
            </Field>
          </div>

          <Field label="Duração" hint="Tempo médio do atendimento, em minutos.">
            <Input
              type="number"
              min="1"
              value={duration}
              onChange={(e) => setDuration(e.target.value)}
              placeholder="Ex.: 60"
            />
          </Field>
          <Field
            label="Sessões padrão"
            hint="Use 1 para serviço avulso. Ex.: combo com 3 sessões = 3."
          >
            <Input
              type="number"
              min="1"
              max="50"
              value={sessionCount}
              onChange={(e) => setSessionCount(e.target.value)}
              placeholder="1"
            />
          </Field>
          <Field
            label="Valor do serviço"
            hint="Preço integral antes de promoções ou sinal de pagamento."
          >
            <Input
              inputMode="decimal"
              value={price}
              onChange={(e) => setPrice(e.target.value)}
              placeholder="Ex.: 150,00"
            />
          </Field>
          <div className="sm:col-span-2">
            <Field label="Resumo" hint="Texto curto exibido no cartão do serviço no catálogo.">
              <Textarea
                value={summary}
                onChange={(e) => setSummary(e.target.value)}
                placeholder="Ex.: Limpeza profissional para remoção de placa e tártaro."
              />
            </Field>
          </div>
          <div className="sm:col-span-2">
            <Field
              label="Descrição completa"
              hint="Explique com mais detalhes o procedimento, benefícios e informações importantes."
            >
              <Textarea
                value={descriptionText}
                onChange={(e) => setDescriptionText(e.target.value)}
                placeholder="Descreva como funciona o atendimento e o que o cliente pode esperar."
                className="min-h-[110px]"
              />
            </Field>
          </div>
        </div>
        <DialogFooter>
          <Button className="w-full sm:w-auto" disabled={busy} onClick={save}>
            {busy ? "Salvando..." : "Salvar serviço"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function PromotionEditor({ services, onSaved }: any) {
  const [open, setOpen] = useState(false);
  const [titleValue, setTitleValue] = useState("");
  const [descriptionValue, setDescriptionValue] = useState("");
  const [serviceId, setServiceId] = useState("all");
  const [discount, setDiscount] = useState("");
  const [promoPrice, setPromoPrice] = useState("");
  const [startsAt, setStartsAt] = useState("");
  const [endsAt, setEndsAt] = useState("");
  const [busy, setBusy] = useState(false);

  const save = async () => {
    if (!titleValue.trim() || (!discount && !promoPrice)) {
      toast.error("Informe o título e o desconto ou preço promocional.");
      return;
    }
    setBusy(true);
    const { error } = await db.from("promotions").insert({
      title: titleValue.trim(),
      description: descriptionValue.trim(),
      service_id: serviceId === "all" ? null : serviceId,
      discount_percent: discount ? Number(discount.replace(",", ".")) : null,
      promotional_price: promoPrice ? Number(promoPrice.replace(",", ".")) : null,
      starts_at: toIso(startsAt),
      ends_at: toIso(endsAt),
      is_active: true,
    });
    setBusy(false);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("Promoção criada.");
    setOpen(false);
    onSaved();
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="h-9 rounded-full px-3 text-xs sm:h-10 sm:px-4 sm:text-sm">
          <Plus className="size-3.5 sm:size-4" /> <span className="sm:hidden">Nova</span>
          <span className="hidden sm:inline">Nova promoção</span>
        </Button>
      </DialogTrigger>
      <DialogContent className="max-h-[92dvh] w-[calc(100%-1rem)] overflow-y-auto rounded-2xl p-5 sm:max-w-lg sm:p-6">
        <DialogHeader>
          <DialogTitle>Nova promoção</DialogTitle>
          <DialogDescription>Defina a oferta e, se desejar, um período.</DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-2 sm:grid-cols-2">
          <div className="sm:col-span-2">
            <Field label="Título">
              <Input value={titleValue} onChange={(e) => setTitleValue(e.target.value)} />
            </Field>
          </div>
          <div className="sm:col-span-2">
            <Field label="Descrição">
              <Textarea
                value={descriptionValue}
                onChange={(e) => setDescriptionValue(e.target.value)}
              />
            </Field>
          </div>
          <div className="sm:col-span-2">
            <Field label="Serviço">
              <Select value={serviceId} onValueChange={setServiceId}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos / institucional</SelectItem>
                  {services.map((s: any) => (
                    <SelectItem key={s.id} value={s.id}>
                      {s.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </Field>
          </div>
          <Field label="Desconto (%)">
            <Input
              inputMode="decimal"
              value={discount}
              onChange={(e) => setDiscount(e.target.value)}
            />
          </Field>
          <Field label="Preço promocional">
            <Input
              inputMode="decimal"
              value={promoPrice}
              onChange={(e) => setPromoPrice(e.target.value)}
            />
          </Field>
          <Field label="Início">
            <Input
              type="datetime-local"
              value={startsAt}
              onChange={(e) => setStartsAt(e.target.value)}
            />
          </Field>
          <Field label="Fim">
            <Input
              type="datetime-local"
              value={endsAt}
              onChange={(e) => setEndsAt(e.target.value)}
            />
          </Field>
        </div>
        <DialogFooter>
          <Button className="w-full sm:w-auto" disabled={busy} onClick={save}>
            {busy ? "Criando..." : "Criar promoção"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function AdminEmailEditor({ onSaved }: any) {
  const [open, setOpen] = useState(false);
  const [email, setEmail] = useState("");
  const [busy, setBusy] = useState(false);

  const save = async () => {
    const normalized = email.trim().toLowerCase();
    if (!normalized.includes("@")) {
      toast.error("Digite um e-mail válido.");
      return;
    }
    setBusy(true);
    const { error } = await db
      .from("admin_emails")
      .upsert({ email: normalized, enabled: true }, { onConflict: "email" });
    setBusy(false);
    if (error) {
      toast.error(error.message);
      return;
    }
    toast.success("E-mail autorizado.");
    setEmail("");
    setOpen(false);
    onSaved();
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" className="h-9 rounded-full px-3 text-xs sm:h-10 sm:px-4 sm:text-sm">
          <Plus className="size-3.5 sm:size-4" /> <span className="sm:hidden">Adicionar</span>
          <span className="hidden sm:inline">Adicionar acesso</span>
        </Button>
      </DialogTrigger>
      <DialogContent className="w-[calc(100%-1rem)] rounded-2xl p-5 sm:max-w-md sm:p-6">
        <DialogHeader>
          <DialogTitle>Autorizar e-mail</DialogTitle>
          <DialogDescription>O usuário ainda precisará entrar na própria conta.</DialogDescription>
        </DialogHeader>
        <Field label="E-mail">
          <Input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="nome@empresa.com"
          />
        </Field>
        <DialogFooter>
          <Button className="w-full sm:w-auto" disabled={busy} onClick={save}>
            {busy ? "Salvando..." : "Autorizar"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function Field({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <Label className="mb-2 block">{label}</Label>
      {children}
      {hint ? (
        <p className="mt-1.5 text-[11px] leading-relaxed text-muted-foreground">{hint}</p>
      ) : null}
    </div>
  );
}

