import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { Check, CreditCard, HandCoins, Landmark, WalletCards } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { z } from "zod";

import { InfinitePayPaymentDialog } from "@/components/infinitepay-payment-dialog";
import { SiteFooter } from "@/components/site-footer";
import { SiteHeader } from "@/components/site-header";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/hooks/use-auth";
import { supabase } from "@/integrations/supabase/client";
import { createBookingAppointment } from "@/lib/booking.functions";
import { getBookingCatalog } from "@/lib/clinic.functions";
import { formatPrice } from "@/lib/clinic";

const title = "Agendar atendimento — JR Clinic";
const description = "Escolha o serviço, profissional, horário e a forma de pagamento do agendamento.";
const db = supabase as any;

const searchSchema = z.object({ servico: z.string().optional() });

export const Route = createFileRoute("/agendar")({
  validateSearch: searchSchema,
  loader: () => getBookingCatalog(),
  head: () => ({
    meta: [
      { title },
      { name: "description", content: description },
      { property: "og:title", content: title },
      { property: "og:description", content: description },
    ],
  }),
  component: Agendar,
});

const weekDays = ["Dom", "Seg", "Ter", "Qua", "Qui", "Sex", "Sáb"];
const days = Array.from({ length: 14 }).map((_, index) => {
  const date = new Date();
  date.setDate(date.getDate() + index);
  const key = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  return {
    key,
    label: String(date.getDate()).padStart(2, "0"),
    weekday: weekDays[date.getDay()],
    weekdayNumber: date.getDay(),
    disabled: date.getDay() === 0,
  };
});

type PaymentChoice = "deposit" | "full" | "onsite";
type PaymentKind = "deposit" | "full";

type BookingPaymentSession = {
  appointmentId: string;
  amount: number;
  total: number;
  balance: number;
  kind: PaymentKind;
  serviceName: string;
  email: string;
};

function Agendar() {
  const { servico } = Route.useSearch();
  const { services, serviceProfessionals, depositPercent } = Route.useLoaderData();
  const navigate = Route.useNavigate();
  const authNavigate = useNavigate();
  const { user } = useAuth();
  const submitAppointment = useServerFn(createBookingAppointment);

  const selectedSlug = servico ?? "";
  const service = services.find((item) => item.slug === selectedSlug);

  const professionals = useMemo(() => {
    if (!service) return [];
    return serviceProfessionals
      .filter((item: any) => item.service_id === service.id && item.professional)
      .map((item: any) => item.professional)
      .sort((a: any, b: any) => Number(a.sort_order ?? 0) - Number(b.sort_order ?? 0));
  }, [service, serviceProfessionals]);

  const [professionalId, setProfessionalId] = useState("");
  const [availableSlots, setAvailableSlots] = useState<any[]>([]);
  const [slotsLoading, setSlotsLoading] = useState(false);
  const [slotsRefreshKey, setSlotsRefreshKey] = useState(0);
  const [day, setDay] = useState(days.find((item) => !item.disabled)?.key ?? days[0]!.key);
  const [time, setTime] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [notes, setNotes] = useState("");
  const [paymentChoice, setPaymentChoice] = useState<PaymentChoice>("deposit");
  const [paymentSession, setPaymentSession] = useState<BookingPaymentSession | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  const selectedProfessional = professionals.find((item: any) => item.id === professionalId) ?? professionals[0];
  const displayedTimeSlots = availableSlots;
  const hasService = Boolean(service);
  const total = Number(service?.price ?? 0);
  const safeDepositPercent = Number.isFinite(Number(depositPercent)) ? Number(depositPercent) : 50;
  const depositValue = hasService
    ? Math.min(total, Math.max(0.01, Math.round(total * safeDepositPercent) / 100))
    : 0;
  const depositLabel = Number.isInteger(safeDepositPercent)
    ? `${safeDepositPercent}%`
    : `${safeDepositPercent.toFixed(1).replace(".", ",")}%`;
  const paymentNow = !hasService
    ? 0
    : paymentChoice === "deposit"
      ? depositValue
      : paymentChoice === "full"
        ? total
        : 0;
  const remaining = !hasService
    ? 0
    : paymentChoice === "deposit"
      ? Math.max(0, total - depositValue)
      : paymentChoice === "full"
        ? 0
        : total;

  const phoneDigits = phone.replace(/\D/g, "");
  const validWhatsApp = phoneDigits.length >= 10 && phoneDigits.length <= 15;

  useEffect(() => {
    setProfessionalId(professionals[0]?.id ?? "");
    setAvailableSlots([]);
    setTime(null);
    setPaymentChoice("deposit");
    setPaymentSession(null);
    setPaymentOpen(false);
  }, [service?.id, professionals]);

  useEffect(() => {
    let cancelled = false;
    setTime(null);

    if (!professionalId || !day) {
      setAvailableSlots([]);
      setSlotsLoading(false);
      return;
    }

    setSlotsLoading(true);
    void db
      .rpc("get_professional_booking_slots", { _professional_id: professionalId, _date: day })
      .then(({ data, error }: any) => {
        if (cancelled) return;
        if (error) {
          console.error("Falha ao carregar horários da data", error);
          setAvailableSlots([]);
          toast.error("Não foi possível carregar os horários desta data.");
        } else {
          setAvailableSlots((data ?? []).filter((slot: any) => slot.is_available));
        }
        setSlotsLoading(false);
      });

    return () => { cancelled = true; };
  }, [professionalId, day, slotsRefreshKey]);

  useEffect(() => {
    if (!professionalId) return;
    const refreshSlots = () => setSlotsRefreshKey((current) => current + 1);
    const refreshWhenVisible = () => { if (document.visibilityState === "visible") refreshSlots(); };
    window.addEventListener("focus", refreshSlots);
    document.addEventListener("visibilitychange", refreshWhenVisible);
    const channel = supabase.channel(`jrclinic-public-booking-slots-${professionalId}`).on(
      "postgres_changes",
      { event: "*", schema: "public", table: "appointments", filter: `professional_id=eq.${professionalId}` },
      refreshSlots,
    ).subscribe();
    return () => {
      window.removeEventListener("focus", refreshSlots);
      document.removeEventListener("visibilitychange", refreshWhenVisible);
      void supabase.removeChannel(channel);
    };
  }, [professionalId]);

  useEffect(() => {
    if (time && !displayedTimeSlots.some((slot: any) => slot.slot === time)) setTime(null);
  }, [displayedTimeSlots, time]);

  useEffect(() => {
    if (!user) return;
    setEmail((current) => current || user.email || "");
    const metadataName = typeof user.user_metadata?.["full_name"] === "string" ? user.user_metadata["full_name"] : "";
    setName((current) => current || metadataName);

    void supabase
      .from("profiles")
      .select("full_name, phone")
      .eq("id", user.id)
      .maybeSingle()
      .then(({ data }) => {
        if (!data) return;
        if (data.full_name) setName((current) => current || data.full_name || "");
        if (data.phone) setPhone((current) => current || data.phone || "");
      });
  }, [user]);

  const resetPreparedPayment = () => {
    setPaymentSession(null);
    setPaymentOpen(false);
  };

  const canConfirm = Boolean(service && professionalId && day && time && name.trim() && email.trim() && validWhatsApp);
  const buttonLabel = busy
    ? "Preparando..."
    : paymentSession
      ? "Retomar pagamento"
      : paymentChoice === "onsite"
        ? "Confirmar agendamento"
        : "Ir para pagamento";

  const confirm = async () => {
    if (paymentSession) {
      setPaymentOpen(true);
      return;
    }

    if (!user) {
      toast.info("Entre na sua conta para concluir o agendamento.");
      await authNavigate({ to: "/auth", search: { next: "/agendar" } });
      return;
    }
    if (!service || !time || !professionalId) return;
    if (!validWhatsApp) {
      toast.error("Informe um WhatsApp válido com DDD para concluir o agendamento.");
      return;
    }

    setBusy(true);
    try {
      const created = await submitAppointment({
        data: {
          serviceId: service.id,
          professionalId,
          patientName: name,
          patientEmail: email,
          patientPhone: phone,
          notes,
          scheduledDate: day,
          scheduledTime: time,
          paymentChoice,
        },
      });

      if (!created.requiresOnlinePayment) {
        toast.success("Agendamento enviado para a clínica.", {
          description: "Pagamento escolhido: presencial, no dia do atendimento.",
        });
        await authNavigate({ to: "/minha-conta" });
        return;
      }

      setPaymentSession({
        appointmentId: created.id,
        amount: Number(created.paymentAmount),
        total: Number(created.total),
        balance: Number(created.balanceAmount),
        kind: created.paymentKind,
        serviceName: service.name,
        email,
      });
      setPaymentOpen(true);

      toast.info(created.paymentKind === "full" ? "Última etapa: pagamento integral" : "Última etapa: pagar o sinal", {
        description: created.paymentKind === "full"
          ? "Pague o valor total pela InfinitePay para concluir a reserva."
          : `Pague ${depositLabel} pela InfinitePay para liberar a reserva.`,
      });
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Não foi possível preparar o agendamento.");
    } finally {
      setBusy(false);
    }
  };

  if (services.length === 0) {
    return (
      <div className="min-h-screen">
        <SiteHeader />
        <main className="mx-auto max-w-3xl px-4 py-16 text-center">
          <h1 className="text-2xl font-semibold">Nenhum serviço disponível</h1>
          <p className="mt-2 text-sm text-muted-foreground">A clínica ainda não publicou serviços para agendamento.</p>
        </main>
        <SiteFooter />
      </div>
    );
  }

  return (
    <div className="min-h-screen w-full max-w-[100dvw] overflow-x-clip">
      <SiteHeader />

      <main className="mx-auto box-border w-full max-w-[1440px] px-4 pb-44 pt-6 sm:px-8 sm:pb-32 sm:pt-10 lg:pb-12">
        <span className="eyebrow text-muted-foreground">Agendamento</span>
        <h1 className="mt-1 text-[28px] font-semibold leading-tight sm:mt-2 sm:text-4xl">Reserve seu horário</h1>
        <p className="mt-2 max-w-[65ch] text-sm leading-relaxed text-muted-foreground sm:mt-3 sm:text-base">
          Escolha o atendimento e depois decida entre pagar {depositLabel} online, quitar tudo online ou pagar presencialmente.
        </p>

        <div className="mt-5 grid grid-cols-5 gap-1 sm:hidden">
          <StepChip number="1" label="Serviço" />
          <StepChip number="2" label="Prof." />
          <StepChip number="3" label="Horário" />
          <StepChip number="4" label="Dados" />
          <StepChip number="5" label="Pagamento" />
        </div>

        <div className="mt-5 grid grid-cols-1 gap-4 sm:mt-10 sm:gap-8 lg:grid-cols-[1.15fr_0.85fr]">
          <div className="space-y-4 sm:space-y-8">
            <section className="rounded-2xl border border-border bg-card p-4 shadow-soft sm:p-6">
              <h2 className="text-base font-semibold sm:text-lg">Serviço e profissional</h2>

              <div className="mt-4">
                <Label htmlFor="servico">Escolha o atendimento</Label>
                <Select value={selectedSlug ?? ""} onValueChange={(value) => { resetPreparedPayment(); navigate({ search: { servico: value }, replace: true }); }}>
                  <SelectTrigger id="servico" className="mt-2 h-11 rounded-xl"><SelectValue placeholder="Selecione um serviço" /></SelectTrigger>
                  <SelectContent>{services.map((item) => <SelectItem key={item.slug} value={item.slug}>{item.name}</SelectItem>)}</SelectContent>
                </Select>
              </div>

              <div className="mt-4">
                <Label htmlFor="profissional">Quem você prefere?</Label>
                <Select value={professionalId ?? ""} disabled={!service} onValueChange={(value) => { setProfessionalId(value); setTime(null); resetPreparedPayment(); }}>
                  <SelectTrigger id="profissional" className="mt-2 h-11 rounded-xl"><SelectValue placeholder={service ? "Escolha o profissional" : "Selecione um serviço primeiro"} /></SelectTrigger>
                  <SelectContent>{professionals.map((item: any) => <SelectItem key={item.id} value={item.id}>{item.name} · {item.specialty}</SelectItem>)}</SelectContent>
                </Select>
                {service && professionals.length === 0 ? <p className="mt-2 text-xs text-destructive">Nenhum profissional está vinculado a este serviço.</p> : null}
              </div>

              <div className="mt-3 flex items-center justify-between rounded-xl bg-secondary/60 px-3 py-2.5 sm:hidden">
                <div><p className="text-xs font-medium">{service ? (selectedProfessional?.name ?? "Escolha o profissional") : "Nenhum serviço selecionado"}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{service ? `${service.duration_min} min` : "Selecione um atendimento para continuar"}</p></div>
                <p className="text-sm font-semibold text-primary">{service ? formatPrice(total) : "—"}</p>
              </div>
            </section>

            <section className="rounded-2xl border border-border bg-card p-4 shadow-soft sm:p-6">
              <h2 className="text-base font-semibold sm:text-lg">Data e horário</h2>
              <div className="mt-4 flex gap-2 overflow-x-auto pb-1 sm:grid sm:grid-cols-7 sm:overflow-visible">
                {days.map((item) => {
                  const unavailable = item.disabled;
                  return <button key={item.key} type="button" disabled={unavailable || !service || !professionalId} onClick={() => { setDay(item.key); setTime(null); resetPreparedPayment(); }} className={`w-[54px] shrink-0 rounded-xl border px-2 py-2.5 text-center transition disabled:opacity-35 sm:w-auto ${day === item.key && service && !unavailable ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background hover:bg-secondary"}`}><span className="block text-[9px] opacity-70">{item.weekday}</span><span className="mt-0.5 block text-sm font-semibold">{item.label}</span></button>;
                })}
              </div>

              <p className="mt-5 text-xs font-medium text-muted-foreground">Horários disponíveis para {selectedProfessional?.name ?? "o profissional"}</p>
              {slotsLoading ? <div className="mt-3 rounded-xl bg-secondary/60 px-3 py-3 text-xs text-muted-foreground">Carregando horários desta data...</div> : (
                <div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4">
                  {displayedTimeSlots.map((slot: any) => (
                    <button key={slot.slot} type="button" disabled={!professionalId || !service} onClick={() => { setTime(slot.slot); resetPreparedPayment(); }} className={`rounded-xl border px-2 py-2.5 text-xs font-medium transition disabled:opacity-35 sm:text-sm ${time === slot.slot ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background hover:bg-secondary"}`}>{slot.slot}</button>
                  ))}
                </div>
              )}
              {professionalId && !slotsLoading && displayedTimeSlots.length === 0 ? <p className="mt-3 text-xs text-destructive">Não há horários liberados para esta data.</p> : null}
            </section>

            <section className="rounded-2xl border border-border bg-card p-4 shadow-soft sm:p-6">
              <h2 className="text-base font-semibold sm:text-lg">Seus dados</h2>
              <div className="mt-4 grid gap-3 sm:grid-cols-2 sm:gap-4">
                <div><Label htmlFor="nome">Nome completo</Label><Input id="nome" value={name} onChange={(e) => { setName(e.target.value); resetPreparedPayment(); }} className="mt-2 h-11 rounded-xl" /></div>
                <div><Label htmlFor="email">E-mail</Label><Input id="email" type="email" value={email} onChange={(e) => { setEmail(e.target.value); resetPreparedPayment(); }} className="mt-2 h-11 rounded-xl" /></div>
                <div className="sm:col-span-2"><Label htmlFor="telefone">WhatsApp <span className="font-semibold text-destructive">*</span></Label><Input id="telefone" inputMode="tel" autoComplete="tel" required value={phone} onChange={(e) => { setPhone(e.target.value); resetPreparedPayment(); }} placeholder="(85) 99999-9999" className={`mt-2 h-11 rounded-xl ${phone && !validWhatsApp ? "border-destructive" : ""}`} />{phone && !validWhatsApp ? <p className="mt-1.5 text-[11px] text-destructive">Informe um número válido com DDD.</p> : <p className="mt-1.5 text-[11px] text-muted-foreground">Obrigatório para confirmações e lembretes do seu agendamento.</p>}</div>
                <div className="sm:col-span-2"><Label htmlFor="obs">Observações <span className="font-normal text-muted-foreground">(opcional)</span></Label><Textarea id="obs" value={notes} onChange={(e) => { setNotes(e.target.value); resetPreparedPayment(); }} className="mt-2 min-h-[82px] resize-none rounded-xl" /></div>
              </div>
            </section>

            <section className="rounded-2xl border border-border bg-card p-4 shadow-soft sm:p-8">
              <div className="text-center"><h2 className="text-lg font-semibold tracking-tight sm:text-2xl">Métodos de pagamento</h2><p className="mx-auto mt-1.5 max-w-[52ch] text-sm leading-relaxed text-muted-foreground">{service ? "Selecione a forma mais conveniente para você. Os detalhes completos aparecem na próxima etapa." : "Selecione um serviço acima para ver os valores reais de cada opção de pagamento."}</p></div>
              <div className="mt-6 grid grid-cols-1 gap-3 sm:grid-cols-3 sm:gap-5">
                <PaymentOption icon={Landmark} selected={paymentChoice === "deposit"} disabled={!service || Boolean(paymentSession)} title={`Pagar ${depositLabel} online`} description="Garanta seu horário pagando o sinal agora e o restante na clínica." value={service ? formatPrice(depositValue) : "—"} badge="Online" onClick={() => { setPaymentChoice("deposit"); resetPreparedPayment(); }} />
                <PaymentOption icon={CreditCard} selected={paymentChoice === "full"} disabled={!service || Boolean(paymentSession)} title="Pagar valor total" description="Agilize seu atendimento com o pagamento integral, seguro e rápido." value={service ? formatPrice(total) : "—"} badge="Online" onClick={() => { setPaymentChoice("full"); resetPreparedPayment(); }} />
                <PaymentOption icon={HandCoins} selected={paymentChoice === "onsite"} disabled={!service || Boolean(paymentSession)} title="Pagar presencialmente" description="Reserve seu horário e pague diretamente na recepção no dia do atendimento." value={service ? "Na clínica" : "—"} badge="Presencial" onClick={() => { setPaymentChoice("onsite"); resetPreparedPayment(); }} />
              </div>
            </section>
          </div>

          <aside className="hidden min-w-0 lg:block">
            <div className="sticky top-[120px] rounded-2xl border border-border bg-card p-6 shadow-soft">
              <h2 className="text-lg font-semibold">Resumo</h2>
              <dl className="mt-4 space-y-3 text-sm">
                <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Serviço</dt><dd className="text-right font-medium">{service?.name ?? "Não selecionado"}</dd></div>
                <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Profissional</dt><dd className="text-right font-medium">{selectedProfessional?.name ?? "—"}</dd></div>
                <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Data</dt><dd className="text-right font-medium">{service ? `${new Date(`${day}T12:00:00`).toLocaleDateString("pt-BR")} · ${time ?? "—"}` : "—"}</dd></div>
                <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Duração</dt><dd className="text-right font-medium">{service ? `${service.duration_min} min` : "—"}</dd></div>
              </dl>
              <Separator className="my-5" />
              <div className="flex items-center justify-between"><span className="text-sm text-muted-foreground">Valor do serviço</span><span className="text-xl font-semibold">{service ? formatPrice(total) : "—"}</span></div>
              <div className="mt-3 rounded-xl bg-primary-soft/60 px-3 py-3"><div className="flex items-center justify-between"><span className="text-sm font-medium text-primary">Pagar agora</span><span className="text-2xl font-semibold text-primary">{service ? formatPrice(paymentNow) : "—"}</span></div><div className="mt-1 flex items-center justify-between text-xs"><span className="text-muted-foreground">Restante</span><span className="font-medium">{service ? formatPrice(remaining) : "—"}</span></div></div>
              <p className="mt-3 text-xs text-muted-foreground">{!service ? "Selecione o serviço para calcular os valores." : paymentChoice === "deposit" ? `${depositLabel} online pela InfinitePay.` : paymentChoice === "full" ? "Pagamento integral online pela InfinitePay." : "Pagamento integral presencial na clínica."}</p>
              <Button size="lg" className="mt-6 w-full rounded-full" disabled={!canConfirm || busy} onClick={confirm}>{buttonLabel}</Button>
            </div>
          </aside>
        </div>
      </main>

      <div className="fixed bottom-[calc(63px+env(safe-area-inset-bottom))] left-0 right-0 z-[60] border-t border-border bg-card/95 px-3 py-2.5 shadow-[0_-8px_30px_rgba(0,0,0,0.06)] backdrop-blur-xl md:bottom-0 lg:hidden">
        <div className="mx-auto flex max-w-lg items-center gap-2.5"><div className="min-w-0 flex-1"><p className="truncate text-[10px] text-muted-foreground">{!service ? "Selecione um serviço" : paymentChoice === "deposit" ? `${depositLabel} online` : paymentChoice === "full" ? "Pagamento total online" : "Pagamento presencial"}</p><p className="text-base font-semibold leading-tight text-primary">{service ? (paymentChoice === "onsite" ? "Na clínica" : formatPrice(paymentNow)) : "—"}</p></div><Button className="h-10 min-w-[146px] shrink-0 rounded-full px-4 text-sm" disabled={!canConfirm || busy} onClick={confirm}>{buttonLabel}</Button></div>
      </div>

      <InfinitePayPaymentDialog open={paymentOpen} onOpenChange={setPaymentOpen} session={paymentSession} />
      <SiteFooter />
    </div>
  );
}

function PaymentOption({ icon: Icon, selected, disabled, title, description, value, badge, onClick }: { icon: typeof WalletCards; selected: boolean; disabled: boolean; title: string; description: string; value: string; badge: string; onClick: () => void; }) {
  return (
    <button type="button" disabled={disabled} onClick={onClick} className={`group relative flex flex-col items-center rounded-2xl border px-4 py-6 text-center transition-all duration-300 disabled:cursor-not-allowed disabled:opacity-45 sm:rounded-3xl sm:p-7 ${selected ? "border-primary bg-primary-soft/50 shadow-soft ring-4 ring-primary/10" : "border-border bg-background hover:-translate-y-1 hover:border-primary/40 hover:shadow-elegant"}`}>
      <span className="absolute -top-2.5 rounded-full bg-secondary px-2.5 py-0.5 text-[9px] font-semibold uppercase tracking-widest text-muted-foreground">{badge}</span>
      <span className={`grid size-12 place-items-center rounded-2xl transition-colors duration-300 sm:size-14 ${selected ? "bg-primary text-primary-foreground" : "bg-primary-soft text-primary group-hover:bg-primary group-hover:text-primary-foreground"}`}><Icon className="size-5 sm:size-6" /></span>
      <p className="mt-4 text-sm font-semibold leading-tight sm:text-base">{title}</p>
      <p className="mt-1.5 hidden text-xs leading-relaxed text-muted-foreground sm:block">{description}</p>
      <p className="mt-3 text-xl font-semibold leading-none text-primary sm:text-2xl">{value}</p>
      <span className={`mt-4 flex w-full items-center justify-center gap-1.5 rounded-xl border py-2.5 text-xs font-semibold transition-all duration-300 ${selected ? "border-primary bg-primary text-primary-foreground" : "border-border text-muted-foreground group-hover:border-primary group-hover:bg-primary group-hover:text-primary-foreground"}`}>{selected ? <><Check className="size-3.5" />Selecionado</> : "Selecionar"}</span>
    </button>
  );
}

function StepChip({ number, label }: { number: string; label: string }) {
  return <div className="flex min-w-0 items-center justify-center gap-1 rounded-xl bg-secondary/70 px-1 py-2"><span className="grid size-4 shrink-0 place-items-center rounded-full bg-primary text-[9px] font-semibold text-primary-foreground">{number}</span><span className="truncate text-[9px] font-medium">{label}</span></div>;
}

import { createFileRoute } from "@tanstack/react-router";
import { Eye, EyeOff } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";

import { SiteFooter } from "@/components/site-footer";
import { SiteHeader } from "@/components/site-header";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useAuth } from "@/hooks/use-auth";
import { supabase } from "@/integrations/supabase/client";

const title = "Entrar na JR Clinic";
const description =
  "Entre ou crie sua conta JR Clinic para acessar agendamentos, perfil e histórico.";
const RECOVERY_TARGET_KEY = "jrclinic:password-recovery-target";
const PUBLIC_APP_ORIGIN = "https://jrclinic.lovable.app";
const db = supabase as any;

function publicAuthOrigin() {
  if (typeof window === "undefined") return PUBLIC_APP_ORIGIN;

  const hostname = window.location.hostname.toLowerCase();
  const localOrPreview =
    hostname === "localhost" ||
    hostname === "127.0.0.1" ||
    hostname === "0.0.0.0" ||
    hostname.endsWith(".localhost") ||
    hostname.includes("lovableproject.com");

  return localOrPreview ? PUBLIC_APP_ORIGIN : window.location.origin;
}

function safeNext(value: unknown) {
  if (typeof value !== "string") return undefined;
  if (!value.startsWith("/") || value.startsWith("//") || value === "/auth") return undefined;
  return value;
}

function isPanelDestination(value?: string) {
  return value === "/profissional" || Boolean(value?.startsWith("/admin"));
}

function adminDestination(value?: string) {
  if (!value || value === "/admin") return "/admin";
  if (value.startsWith("/admin/equipe")) return "/admin#equipe";
  if (value.startsWith("/admin/acessos")) return "/admin#acessos";
  if (value.startsWith("/admin/financeiro")) return "/admin#financeiro";
  if (value.startsWith("/admin/catalogo")) return "/admin#catalogo";
  return "/admin";
}

async function resolveAuthenticatedDestination(next?: string) {
  const { data: destination, error } = await db.rpc("current_portal_destination");
  if (error) throw error;

  if (destination === "admin") return adminDestination(next);
  if (destination === "professional") return "/profissional";
  if (isPanelDestination(next)) return null;
  return next ?? "/";
}

export const Route = createFileRoute("/auth")({
  validateSearch: (search: Record<string, unknown>) => ({
    next: safeNext(search["next"]),
  }),
  head: () => ({
    meta: [
      { title },
      { name: "description", content: description },
      { property: "og:title", content: title },
      { property: "og:description", content: description },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: AuthPage,
});

function PasswordField({
  id,
  value,
  onChange,
  autoComplete,
  placeholder,
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  autoComplete: string;
  placeholder?: string;
}) {
  const [visible, setVisible] = useState(false);

  return (
    <div className="relative mt-2">
      <Input
        id={id}
        type={visible ? "text" : "password"}
        autoComplete={autoComplete}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        className="h-11 rounded-xl pr-11"
        placeholder={placeholder}
      />
      <button
        type="button"
        onClick={() => setVisible((current) => !current)}
        className="absolute right-1.5 top-1/2 grid size-8 -translate-y-1/2 place-items-center rounded-lg text-muted-foreground transition hover:bg-secondary hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        aria-label={visible ? "Ocultar senha" : "Mostrar senha"}
        title={visible ? "Ocultar senha" : "Mostrar senha"}
      >
        {visible ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
      </button>
    </div>
  );
}

function AuthPage() {
  const { user, loading } = useAuth();
  const { next } = Route.useSearch();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [whatsapp, setWhatsapp] = useState("");
  const [birthDate, setBirthDate] = useState("");
  const [busy, setBusy] = useState(false);
  const [resetBusy, setResetBusy] = useState(false);
  const [checkingAccess, setCheckingAccess] = useState(false);

  const finishAuthenticatedLogin = async () => {
    setCheckingAccess(true);
    try {
      const destination = await resolveAuthenticatedDestination(next);
      if (destination) {
        window.location.replace(destination);
        return;
      }

      toast.error("Este e-mail não está autorizado a acessar o painel da JR Clinic.");
      await supabase.auth.signOut();
      setCheckingAccess(false);
    } catch (accessError: any) {
      console.error(accessError);
      toast.error("Não foi possível verificar seu acesso agora. Tente novamente.");
      setCheckingAccess(false);
    }
  };

  useEffect(() => {
    if (loading || !user || checkingAccess || busy) return;
    void finishAuthenticatedLogin();
    // finishAuthenticatedLogin is intentionally driven only by authenticated state/search target.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, user, next]);

  const signIn = async () => {
    if (!email.trim() || !password) {
      toast.error("Digite seu e-mail e senha.");
      return;
    }

    setBusy(true);
    setCheckingAccess(true);
    const { error } = await supabase.auth.signInWithPassword({
      email: email.trim(),
      password,
    });

    if (error) {
      setBusy(false);
      setCheckingAccess(false);
      if (error.message.toLowerCase().includes("invalid login credentials")) {
        toast.error("E-mail ou senha incorretos. Se necessário, use ‘Esqueci minha senha’. ");
      } else {
        toast.error(error.message);
      }
      return;
    }

    try {
      const destination = await resolveAuthenticatedDestination(next);
      if (destination) {
        toast.success("Bem-vindo de volta!");
        window.location.replace(destination);
        return;
      }

      await supabase.auth.signOut();
      toast.error("Este e-mail não está autorizado a acessar o painel da JR Clinic.");
    } catch (accessError: any) {
      console.error(accessError);
      toast.error("Login realizado, mas não foi possível verificar seu acesso. Tente novamente.");
    } finally {
      setBusy(false);
      setCheckingAccess(false);
    }
  };

  const sendPasswordReset = async () => {
    const normalizedEmail = email.trim();
    if (!normalizedEmail) {
      toast.error("Digite seu e-mail primeiro.");
      return;
    }

    setResetBusy(true);
    const recoveryTarget = next === "/profissional" ? "/profissional" : next?.startsWith("/admin") ? "/admin" : "/minha-conta";
    window.localStorage.setItem(RECOVERY_TARGET_KEY, recoveryTarget);

    const redirectTo = `${publicAuthOrigin()}/redefinir-senha`;
    const { error } = await supabase.auth.resetPasswordForEmail(normalizedEmail, {
      redirectTo,
    });
    setResetBusy(false);

    if (error) {
      window.localStorage.removeItem(RECOVERY_TARGET_KEY);
      toast.error(error.message);
      return;
    }

    toast.success("Link de recuperação enviado", {
      description: "Confira seu e-mail e abra o link mais recente para criar uma nova senha.",
    });
  };

  const signUp = async () => {
    const panelSignup = isPanelDestination(next);
    const normalizedWhatsApp = whatsapp.replace(/\D/g, "");
    const today = new Date();
    const todayLocal = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, "0")}-${String(today.getDate()).padStart(2, "0")}`;

    if (!name.trim() || !email.trim() || password.length < 8) {
      toast.error("Preencha nome, e-mail e uma senha de pelo menos 8 caracteres.");
      return;
    }

    if (!panelSignup) {
      if (normalizedWhatsApp.length < 10) {
        toast.error("Informe um WhatsApp válido com DDD.");
        return;
      }
      if (!birthDate || birthDate > todayLocal) {
        toast.error("Informe uma data de nascimento válida.");
        return;
      }
    }

    setBusy(true);
    const redirectTo = `${publicAuthOrigin()}/auth${next ? `?next=${encodeURIComponent(next)}` : ""}`;
    const { error } = await supabase.auth.signUp({
      email: email.trim(),
      password,
      options: {
        emailRedirectTo: redirectTo,
        data: panelSignup
          ? { full_name: name.trim(), account_type: "panel" }
          : {
              full_name: name.trim(),
              whatsapp: normalizedWhatsApp,
              phone: normalizedWhatsApp,
              birth_date: birthDate,
              account_type: "client",
            },
      },
    });
    setBusy(false);

    if (error) {
      toast.error(error.message);
      return;
    }

    toast.success("Conta criada! Verifique seu e-mail se a confirmação for solicitada.");
  };

  const isAdminAccess = isPanelDestination(next);

  return (
    <div className="min-h-screen overflow-x-hidden">
      <SiteHeader />

      <main className="mx-auto max-w-md px-4 pb-24 pt-8 sm:px-8 sm:py-16">
        <span className="eyebrow text-muted-foreground">
          {isAdminAccess ? "Acesso ao painel" : "Bem-vindo"}
        </span>
        <h1 className="mt-2 text-3xl font-semibold">
          {isAdminAccess ? "Painel JR Clinic" : "Sua conta JR Clinic"}
        </h1>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">
          {isAdminAccess
            ? "Entre com um e-mail administrativo ou de colaborador previamente autorizado."
            : "Entre para agendar, acompanhar atendimentos e manter seus dados em um só lugar."}
        </p>

        <div className="mt-7 rounded-2xl border border-border bg-card p-5 shadow-soft sm:mt-8 sm:p-6">
          {isAdminAccess && (
            <p className="mb-5 text-center text-[11px] leading-relaxed text-muted-foreground">
              Administradores acessam a gestão completa. Colaboradores autorizados são direcionados automaticamente à própria agenda.
            </p>
          )}

          <Tabs defaultValue="entrar">
            <TabsList className="w-full">
              <TabsTrigger value="entrar" className="flex-1">Entrar</TabsTrigger>
              <TabsTrigger value="criar" className="flex-1">Criar conta</TabsTrigger>
            </TabsList>

            <TabsContent value="entrar" className="mt-5 space-y-4">
              <div>
                <Label htmlFor="email">E-mail</Label>
                <Input
                  id="email"
                  type="email"
                  autoComplete="email"
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  className="mt-2 h-11 rounded-xl"
                  placeholder="voce@email.com"
                />
              </div>
              <div>
                <div className="flex items-center justify-between gap-3">
                  <Label htmlFor="senha">Senha</Label>
                  <button
                    type="button"
                    onClick={sendPasswordReset}
                    disabled={resetBusy}
                    className="text-xs font-medium text-primary transition-opacity hover:opacity-75 disabled:opacity-50"
                  >
                    {resetBusy ? "Enviando..." : "Esqueci minha senha"}
                  </button>
                </div>
                <PasswordField
                  id="senha"
                  autoComplete="current-password"
                  value={password}
                  onChange={setPassword}
                />
              </div>
              <Button
                className="h-11 w-full rounded-full"
                disabled={busy || checkingAccess}
                onClick={signIn}
              >
                {checkingAccess ? "Verificando acesso..." : busy ? "Entrando..." : "Entrar"}
              </Button>
            </TabsContent>

            <TabsContent value="criar" className="mt-5 space-y-4">
              <div>
                <Label htmlFor="nome">Nome completo</Label>
                <Input
                  id="nome"
                  autoComplete="name"
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  className="mt-2 h-11 rounded-xl"
                  placeholder="Seu nome"
                />
              </div>
              {!isAdminAccess && (
                <>
                  <div>
                    <Label htmlFor="whatsapp-novo">WhatsApp</Label>
                    <Input
                      id="whatsapp-novo"
                      inputMode="tel"
                      autoComplete="tel"
                      value={whatsapp}
                      onChange={(event) => setWhatsapp(event.target.value)}
                      className="mt-2 h-11 rounded-xl"
                      placeholder="(85) 99999-9999"
                    />
                  </div>
                  <div>
                    <Label htmlFor="nascimento-novo">Data de nascimento</Label>
                    <Input
                      id="nascimento-novo"
                      type="date"
                      value={birthDate}
                      onChange={(event) => setBirthDate(event.target.value)}
                      className="mt-2 h-11 rounded-xl"
                    />
                  </div>
                </>
              )}
              <div>
                <Label htmlFor="email-novo">E-mail</Label>
                <Input
                  id="email-novo"
                  type="email"
                  autoComplete="email"
                  value={email}
                  onChange={(event) => setEmail(event.target.value)}
                  className="mt-2 h-11 rounded-xl"
                  placeholder="voce@email.com"
                />
              </div>
              <div>
                <Label htmlFor="senha-nova">Senha</Label>
                <PasswordField
                  id="senha-nova"
                  autoComplete="new-password"
                  value={password}
                  onChange={setPassword}
                  placeholder="Mínimo de 8 caracteres"
                />
              </div>
              <Button
                className="h-11 w-full rounded-full"
                disabled={busy || checkingAccess}
                onClick={signUp}
              >
                {busy ? "Criando..." : "Criar conta"}
              </Button>
            </TabsContent>
          </Tabs>
        </div>

        {!isAdminAccess && (
          <p className="mt-5 text-center text-[11px] leading-relaxed text-muted-foreground">
            Sua conta será usada para vincular seus agendamentos, histórico e futuros pagamentos.
          </p>
        )}
      </main>

      <SiteFooter />
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { Search, Sparkles } from "lucide-react";
import { useState } from "react";
import { z } from "zod";

import { ServiceCard } from "@/components/service-card";
import { SiteFooter } from "@/components/site-footer";
import { SiteHeader } from "@/components/site-header";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { getCatalogPresentation } from "@/lib/catalog-presentation.functions";
import { getCatalog } from "@/lib/clinic.functions";

const title = "Catálogo de serviços — JR Clinic";
const description =
  "Explore consultas, nutrição, psicologia, fisioterapia e exames da JR Clinic por categoria, duração e valor.";

const searchSchema = z.object({
  categoria: z.string().optional(),
});

export const Route = createFileRoute("/catalogo")({
  validateSearch: searchSchema,
  loader: async () => {
    const [catalog, presentation] = await Promise.all([
      getCatalog(),
      getCatalogPresentation(),
    ]);
    return { ...catalog, ...presentation };
  },
  staleTime: 5 * 60 * 1000,
  preloadStaleTime: 5 * 60 * 1000,
  head: () => ({
    meta: [
      { title },
      { name: "description", content: description },
      { property: "og:title", content: title },
      { property: "og:description", content: description },
    ],
  }),
  component: Catalogo,
});

function Catalogo() {
  const catalog = Route.useLoaderData();
  const { categoria } = Route.useSearch();
  const navigate = Route.useNavigate();
  const [query, setQuery] = useState("");

  const services = catalog.services.map((service) => ({
    slug: service.slug,
    name: service.name,
    categoryId: service.category_id,
    professional: service.professional,
    professionalRole: service.professional_role,
    durationMin: service.duration_min,
    price: Number(service.price),
    rating: Number(service.rating),
    reviewsCount: service.reviews_count,
    summary: service.summary,
    description: service.description,
    includes: service.includes,
    preparation: service.preparation,
    reviews: [],
  }));
  const categories = catalog.categories;

  const filtered = services.filter((service) => {
    const matchesCategory = !categoria || service.categoryId === categoria;
    const q = query.trim().toLowerCase();
    const matchesQuery =
      !q ||
      service.name.toLowerCase().includes(q) ||
      service.professional.toLowerCase().includes(q) ||
      service.summary.toLowerCase().includes(q);
    return matchesCategory && matchesQuery;
  });

  const groupedCategories = categories
    .map((category) => ({
      ...category,
      services: filtered.filter((service) => service.categoryId === category.id),
    }))
    .filter((category) => category.services.length > 0);

  const effectiveFeaturedId =
    catalog.featuredCategoryId ?? groupedCategories[0]?.id ?? null;

  const displayCategories = [...groupedCategories].sort((a, b) => {
    if (a.id === effectiveFeaturedId) return -1;
    if (b.id === effectiveFeaturedId) return 1;
    return a.sort_order - b.sort_order;
  });

  const setCategory = (id?: string) =>
    navigate({ search: id ? { categoria: id } : {}, replace: true });

  return (
    <div className="min-h-screen">
      <SiteHeader />

      <main className="mx-auto max-w-[1440px] px-4 pb-10 pt-6 sm:px-8 sm:py-14 lg:py-20">
        <span className="eyebrow text-accent max-sm:text-[10px]">Catálogo</span>
        <h1 className="mt-1 text-[29px] font-semibold leading-tight text-primary sm:mt-2 sm:text-5xl">
          Serviços da JR Clinic
        </h1>
        <p className="mt-2 max-w-[52ch] text-sm leading-relaxed text-muted-foreground sm:mt-3 sm:text-base">
          {services.length} serviços organizados em {categories.length} categorias.
          <span className="hidden sm:inline"> Navegue por especialidade ou busque pelo nome do serviço ou profissional.</span>
        </p>

        <div className="relative mt-5 max-w-md sm:mt-8">
          <Search className="pointer-events-none absolute left-4 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Buscar serviço ou profissional"
            className="h-11 rounded-full border-border bg-card pl-10 pr-4 text-sm shadow-soft sm:h-12 sm:px-5 sm:pl-11"
            aria-label="Buscar serviço"
          />
        </div>

        <div className="sticky top-14 z-30 -mx-4 mt-4 flex gap-2 overflow-x-auto bg-background/95 px-4 pb-4 pt-2.5 backdrop-blur-xl [scrollbar-width:thin] [scrollbar-color:rgb(15_77_62_/_0.14)_transparent] [&::-webkit-scrollbar]:h-[2px] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-primary/15 [&::-webkit-scrollbar-track]:bg-transparent sm:top-16 sm:-mx-8 sm:mt-8 sm:px-8 sm:pb-3 sm:pt-3">
          <Button
            variant={categoria ? "outline" : "default"}
            size="sm"
            className="h-8 shrink-0 rounded-full px-3 text-xs sm:h-9 sm:text-sm"
            onClick={() => setCategory(undefined)}
          >
            Todas as categorias
          </Button>
          {categories.map((category) => (
            <Button
              key={category.id}
              variant={categoria === category.id ? "default" : "outline"}
              size="sm"
              className="h-8 shrink-0 rounded-full px-3 text-xs sm:h-9 sm:text-sm"
              onClick={() => setCategory(category.id)}
            >
              {category.name}
            </Button>
          ))}
        </div>

        <div className="mt-3 flex items-center justify-between sm:mt-6">
          <p className="text-[11px] text-muted-foreground sm:text-xs">
            {filtered.length === 1 ? "1 resultado" : `${filtered.length} resultados`}
          </p>
        </div>

        {filtered.length === 0 ? (
          <div className="mt-8 rounded-2xl border border-dashed border-border bg-card px-5 py-8 text-center sm:mt-12">
            <p className="text-sm font-medium">Nenhum serviço encontrado</p>
            <p className="mt-1 text-xs text-muted-foreground">Tente outro termo ou categoria.</p>
          </div>
        ) : (
          <div className="mt-5 space-y-10 sm:mt-8 sm:space-y-14">
            {displayCategories.map((category, categoryIndex) => {
              const isFeatured = category.id === effectiveFeaturedId && !categoria;
              const compactThree = !isFeatured && categoryIndex % 2 === 1;

              return (
                <section key={category.id} id={`categoria-${category.id}`} className="scroll-mt-36">
                  <div className="relative overflow-hidden rounded-[18px] border border-primary/15 bg-primary px-4 py-4 shadow-[0_14px_34px_-30px_rgba(15,77,62,0.65)] sm:px-5 sm:py-4.5">
                    <div className="pointer-events-none absolute inset-y-0 left-0 w-1 bg-white/22" />
                    <div className="pointer-events-none absolute inset-y-0 right-0 w-16 border-l border-white/7 bg-white/[0.025]" />

                    <div className="relative flex min-w-0 items-center gap-3 sm:gap-4">
                      <div className="flex size-9 shrink-0 items-center justify-center rounded-[10px] border border-white/14 bg-white/[0.07] text-[10px] font-semibold tracking-[0.08em] text-primary-foreground/80 sm:size-10 sm:text-[11px]">
                        {String(categoryIndex + 1).padStart(2, "0")}
                      </div>

                      <div className="min-w-0 flex-1 sm:flex sm:items-center sm:gap-5">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2">
                            <span className="block text-[8px] font-semibold uppercase tracking-[0.2em] text-primary-foreground/50 sm:text-[9px]">
                              Categoria
                            </span>
                            {isFeatured ? (
                              <span className="inline-flex items-center gap-1 rounded-full border border-white/14 bg-white/[0.08] px-2 py-0.5 text-[8px] font-semibold uppercase tracking-[0.12em] text-primary-foreground/75 sm:text-[9px]">
                                <Sparkles className="size-2.5" />
                                Em evidência
                              </span>
