          <ArrowLeft className="size-3.5 sm:size-4" />
          Voltar ao catálogo
        </Link>

        <div className="mt-5 grid gap-7 sm:mt-8 sm:gap-10 lg:grid-cols-[1.15fr_0.85fr]">
